       variants=(('95fdd9762320b03cdced5ba411d724bf645fc0c1f94cc6d4fddb5f4b6fb06c40', (('        keywords: ["tables", "statement", "ledger", "line items", "csv", "xlsx", "export", "reconcile"],\n      },\n', '        keywords: ["tables", "statement", "ledger", "line items", "csv", "xlsx", "export", "reconcile"],\n      },\n      // ARCH46-S2:nav-obligations\n      {\n        id: "obligations",\n        name: "Obligations",\n        route: "workspaceObligations",\n        path: obligationsPath(orgSlug, workspaceSlug),\n        icon: CalendarClock,\n        description: "Renewals, notice deadlines, payments and reports read from documents, on a calendar",\n        capability: CAPABILITY.obligations,\n        keywords: ["obligations", "deadlines", "renewal", "notice", "due date", "calendar", "ical", "expiry", "reminder"],\n      },\n'), ('  corroborationsPath,\n  createWorkspacePath,\n', '  corroborationsPath,\n  obligationsPath,\n  createWorkspacePath,\n'), ('  Bell,\n  ClipboardCheck,\n', '  Bell,\n  CalendarClock,\n  ClipboardCheck,\n'))),),
