    Op(path='frontend/src/components/obligations/CalendarFeeds.tsx', kind='new', final_sha='0961ddcc764ac38bc8721b07539011a71d3aeb6057b0dc3140b6fa77f515fad4',
       variants=(),
       content='/**\n * ARCH46-S2:calendar-feeds — subscribe a calendar app (Google, Outlook, Apple)\n * to the workspace\'s obligations. The URL carries a signed token that is shown\n * ONCE, here, when it is issued; the server keeps only its SHA-256. Revoking a\n * feed takes effect on the calendar app\'s next poll (nothing caches a feed).\n * Each member manages their own feeds; an administrator can revoke anyone\'s.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Check, Copy, Link2, Loader2, XCircle } from "lucide-react";\n\nimport { BUTTON_DESTRUCTIVE, BUTTON_GHOST, BUTTON_PRIMARY, FIELD_LABEL, HINT, INPUT, SELECT, SURFACE } from "@/components/ui/primitives";\nimport { feedUrls, issueFeed, listFeeds, obligationKeys, revokeFeed } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport type { FeedIssued } from "@/types/obligations";\nimport { formatDateTime } from "@/utils/formatters";\n\ninterface Props {\n  readonly workspaceId: string;\n}\n\nexport const CalendarFeeds: React.FC<Props> = ({ workspaceId }) => {\n  const queryClient = useQueryClient();\n  const query = useQuery({ queryKey: obligationKeys.feeds(workspaceId), queryFn: () => listFeeds(workspaceId),\n    enabled: Boolean(workspaceId) });\n  const [label, setLabel] = useState("My obligations");\n  const [scope, setScope] = useState("MINE");\n  const [includeClosed, setIncludeClosed] = useState(true);\n  const [expires, setExpires] = useState("");\n  const [issued, setIssued] = useState<FeedIssued | null>(null);\n  const [copied, setCopied] = useState(false);\n  const refresh = (): void => {\n    void queryClient.invalidateQueries({ queryKey: obligationKeys.feeds(workspaceId) });\n  };\n  const issue = useMutation({\n    mutationFn: () => {\n      const days = expires ? Number.parseInt(expires, 10) : null;\n      return issueFeed(workspaceId, {\n        label: label.trim() || "Obligations", scope, include_closed: includeClosed,\n        ...(days && !Number.isNaN(days) ? { expires_in_days: days } : {}),\n      });\n    },\n    onSuccess: (result) => { setIssued(result); setCopied(false); refresh(); },\n  });\n  const revoke = useMutation({ mutationFn: (id: string) => revokeFeed(workspaceId, id), onSuccess: refresh });\n  const urls = issued ? feedUrls(issued.token) : null;\n  const copy = async (): Promise<void> => {\n    if (urls) {\n      await navigator.clipboard.writeText(urls.https);\n      setCopied(true);\n    }\n  };\n\n  return (\n    <div className="space-y-4">\n      <p className={HINT}>\n        A feed is a private link: anyone holding it can read the obligations it covers, so treat it like a password and\n        revoke it if it leaks. It shows each due date as an all-day event in your calendar, with a reminder at the\n        obligation&apos;s lead time.\n      </p>\n      <form className={`${SURFACE} space-y-3 p-4`} aria-label="New calendar feed"\n        onSubmit={(event) => { event.preventDefault(); issue.mutate(); }}>\n        <div className="grid gap-3 md:grid-cols-4">\n          <label className="space-y-1 md:col-span-2">\n            <span className={FIELD_LABEL}>Label</span>\n            <input className={INPUT} value={label} maxLength={100} onChange={(e) => setLabel(e.target.value)} />\n          </label>\n          <label className="space-y-1">\n            <span className={FIELD_LABEL}>Covers</span>\n            <select className={SELECT} value={scope} onChange={(e) => setScope(e.target.value)}>\n              <option value="MINE">Obligations I own</option>\n              <option value="ALL">Every obligation in the workspace</option>\n            </select>\n          </label>\n          <label className="space-y-1">\n            <span className={FIELD_LABEL}>Expires after (days)</span>\n            <input type="number" min={1} max={3650} className={INPUT} value={expires} placeholder="Never"\n              onChange={(e) => setExpires(e.target.value)} />\n          </label>\n        </div>\n        <label className="inline-flex items-center gap-2 text-sm">\n          <input type="checkbox" checked={includeClosed} onChange={(e) => setIncludeClosed(e.target.checked)} />\n          Keep recently done and waived obligations on the calendar\n        </label>\n        {issue.isError ? <p className="text-sm text-destructive">{errorMessage(issue.error, "The feed could not be created.")}</p> : null}\n        <button type="submit" className={BUTTON_PRIMARY} disabled={issue.isPending}>\n          {issue.isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Link2 className="h-4 w-4" aria-hidden />}\n          Create feed link\n        </button>\n      </form>\n      {issued && urls ? (\n        <div className="space-y-2 rounded-lg border border-primary/40 bg-primary/5 p-3" role="status">\n          <p className="text-sm font-semibold">Copy this link now: it is shown only once.</p>\n          <div className="flex flex-wrap items-center gap-2">\n            <code className="max-w-full flex-1 break-all rounded bg-background px-2 py-1 text-xs">{urls.https}</code>\n            <button type="button" className={BUTTON_GHOST} onClick={() => void copy()}>\n              {copied ? <Check className="h-4 w-4" aria-hidden /> : <Copy className="h-4 w-4" aria-hidden />} {copied ? "Copied" : "Copy"}\n            </button>\n            <a className={BUTTON_GHOST} href={urls.webcal}>Open in my calendar app</a>\n          </div>\n          <p className={HINT}>In Google Calendar: Other calendars → From URL. In Outlook: Add calendar → Subscribe from web.</p>\n        </div>\n      ) : null}\n      {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "Feeds could not be loaded.")}</p> : null}\n      <ul className="space-y-2">\n        {(query.data?.items ?? []).map((feed) => (\n          <li key={feed.id} className={`${SURFACE} flex flex-wrap items-center gap-2 p-3 text-sm ${feed.revoked_at ? "opacity-60" : ""}`}>\n            <span className="font-semibold">{feed.label}</span>\n            <span className={HINT}>\n              {feed.scope === "MINE" ? "my obligations" : "whole workspace"} · created {formatDateTime(feed.created_at)}\n              {feed.last_used_at ? ` · last read ${formatDateTime(feed.last_used_at)} (${feed.use_count}×)` : " · never read"}\n              {feed.expires_at ? ` · expires ${formatDateTime(feed.expires_at)}` : ""}\n              {feed.mine ? "" : " · another member\'s"}\n            </span>\n            {feed.revoked_at ? (\n              <span className="ml-auto inline-flex items-center gap-1 text-xs text-muted-foreground">\n                <XCircle className="h-3.5 w-3.5" aria-hidden /> Revoked {formatDateTime(feed.revoked_at)}\n              </span>\n            ) : (\n              <button type="button" className={`${BUTTON_DESTRUCTIVE} ml-auto`} disabled={revoke.isPending}\n                onClick={() => { if (window.confirm(`Revoke "${feed.label}"? Calendars subscribed to it stop updating.`)) { revoke.mutate(feed.id); } }}>\n                Revoke\n              </button>\n            )}\n          </li>\n        ))}\n        {query.data && query.data.items.length === 0 ? <li className={HINT}>No feeds yet.</li> : null}\n      </ul>\n    </div>\n  );\n};\n\nexport default CalendarFeeds;\n'),
    Op(path='frontend/src/components/obligations/DocumentObligations.tsx', kind='new', final_sha='f333c38ef58e803172a96e85df86b7da4aec5ef04edbcb0fe0d28a0a0dc3c88a',
       variants=(),
       content='/**\n * ARCH46-S2:document-obligations — the Obligations tab on Work Item details:\n * every renewal, notice deadline, payment, delivery, expiry and report read\n * from this document, with its due date in the workspace\'s zone, and "Read\n * again" (contributors) to re-run the deterministic extraction after an edit.\n * Locked without capability.obligations.\n */\nimport React from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Link, useParams } from "react-router-dom";\nimport { CalendarClock, Loader2, Lock, RefreshCw } from "lucide-react";\n\nimport ObligationTable from "@/components/obligations/ObligationTable";\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { BUTTON_GHOST, HINT, SURFACE_INSET } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { obligationsPath } from "@/routes/tenantPaths";\nimport { extractDocumentObligations, getDocumentObligations, obligationKeys } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\n\nexport const DocumentObligations: React.FC<{ readonly workItemId: string }> = ({ workItemId }) => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "" } = useParams<{ orgSlug: string; workspaceSlug: string }>();\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.obligations);\n  const canEdit = workspace?.role === "ADMIN" || workspace?.role === "OWNER" || workspace?.role === "CONTRIBUTOR";\n  const queryClient = useQueryClient();\n  const query = useQuery({\n    queryKey: obligationKeys.document(workspaceId, workItemId),\n    queryFn: () => getDocumentObligations(workspaceId, workItemId),\n    enabled: Boolean(workspaceId && workItemId && capability.granted),\n  });\n  const again = useMutation({\n    mutationFn: () => extractDocumentObligations(workspaceId, workItemId),\n    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: obligationKeys.all(workspaceId) }); },\n  });\n\n  if (!capability.granted) {\n    return (\n      <section className={`${SURFACE_INSET} flex items-center gap-2 p-3 text-sm`} aria-label="Obligations">\n        <Lock className="h-4 w-4" aria-hidden />\n        <span>Renewals, notice deadlines and payments read from documents are included on the Business and Enterprise plans.</span>\n      </section>\n    );\n  }\n  return (\n    <section className="space-y-3" aria-labelledby="document-obligations-title">\n      <div className="flex flex-wrap items-center gap-2">\n        <CalendarClock className="h-5 w-5 text-muted-foreground" aria-hidden />\n        <h2 id="document-obligations-title" className="text-lg font-bold">Obligations</h2>\n        <Link to={obligationsPath(orgSlug, workspaceSlug)} className="text-xs font-semibold text-primary hover:underline">All obligations</Link>\n        {canEdit ? (\n          <button type="button" className={`${BUTTON_GHOST} ml-auto`} disabled={again.isPending} onClick={() => again.mutate()}>\n            {again.isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <RefreshCw className="h-4 w-4" aria-hidden />}\n            Read again\n          </button>\n        ) : null}\n      </div>\n      <p className={HINT}>\n        Read deterministically from the document&apos;s clauses and fields — no model is called. Dates the document leaves in\n        doubt wait for a person to confirm them in the review hub.\n      </p>\n      {again.data ? (\n        <p className="text-xs text-muted-foreground" aria-live="polite">\n          {again.data.created} new, {again.data.kept} unchanged, {again.data.superseded} no longer in the document\n          {again.data.pending ? `, ${again.data.pending} to confirm` : ""}.\n        </p>\n      ) : null}\n      {again.isError ? <p className="text-sm text-destructive">{errorMessage(again.error, "The document could not be read again.")}</p> : null}\n      {query.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n      {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "Obligations could not be loaded.")}</p> : null}\n      {query.data ? (\n        <ObligationTable rows={query.data.items} orgSlug={orgSlug} workspaceSlug={workspaceSlug} hideDocument\n          empty="No obligations were read from this document." />\n      ) : null}\n    </section>\n  );\n};\n\nexport default DocumentObligations;\n'),
    Op(path='frontend/src/components/obligations/EntityObligations.tsx', kind='new', final_sha='d195f53da19cd67d3250c2048357257eddd9268a4dd13996a6854c530638feeb',
       variants=(),
       content='/**\n * ARCH46-S2:entity-obligations — the Obligations section of Entity 360: every\n * obligation tied to this record or to any record merged into it (obligations\n * hang off the record that was the root when they were read, and a later merge\n * must not orphan them). Locked without capability.obligations.\n */\nimport React from "react";\nimport { useQuery } from "@tanstack/react-query";\nimport { Link } from "react-router-dom";\nimport { Loader2, Lock } from "lucide-react";\n\nimport ObligationTable from "@/components/obligations/ObligationTable";\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { HINT } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { obligationsPath } from "@/routes/tenantPaths";\nimport { getEntityObligations, obligationKeys } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\n\ninterface Props {\n  readonly entityId: string;\n  readonly orgSlug: string;\n  readonly workspaceSlug: string;\n}\n\nexport const EntityObligations: React.FC<Props> = ({ entityId, orgSlug, workspaceSlug }) => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.obligations);\n  const query = useQuery({\n    queryKey: obligationKeys.entity(workspaceId, entityId),\n    queryFn: () => getEntityObligations(workspaceId, entityId),\n    enabled: Boolean(workspaceId && entityId && capability.granted),\n  });\n  if (!capability.granted) {\n    return (\n      <p className={`${HINT} flex items-center gap-2`}>\n        <Lock className="h-3.5 w-3.5" aria-hidden />\n        Renewals, notice periods and other obligations tied to this record are included on the Business and Enterprise plans.\n      </p>\n    );\n  }\n  if (query.isLoading) {\n    return <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" />;\n  }\n  if (query.isError) {\n    return <p className="text-sm text-destructive">{errorMessage(query.error, "Obligations could not be loaded.")}</p>;\n  }\n  const rows = query.data?.items ?? [];\n  return (\n    <div className="space-y-2">\n      <ObligationTable rows={rows} orgSlug={orgSlug} workspaceSlug={workspaceSlug} hideParty\n        empty="No obligations are tied to this record yet." />\n      {rows.length > 0 ? (\n        <Link className="text-xs font-semibold text-primary hover:underline" to={`${obligationsPath(orgSlug, workspaceSlug)}?entity=${encodeURIComponent(entityId)}`}>\n          Open in Obligations\n        </Link>\n      ) : null}\n    </div>\n  );\n};\n\nexport default EntityObligations;\n'),
    Op(path='frontend/src/components/obligations/HolidayCalendars.tsx', kind='new', final_sha='c1bada0fbcce8ea59c68844b754c97c7aa02ccab4aa9c2134f1e36270b85e338',
       variants=(),
       content='/**\n * ARCH46-S2:holiday-calendars — the stored calendars business days are counted\n * on. A calendar is generated from a built-in template for the years asked\n * (US federal, England & Wales, India national), pasted as "YYYY-MM-DD Name"\n * lines, or imported from an .ics file; nothing is fetched from a calendar\n * service. Editing one reschedules every obligation that counts with it.\n * Administrators change them; everyone can read them.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { CalendarDays, Loader2, Star, Trash2 } from "lucide-react";\n\nimport { BUTTON_DESTRUCTIVE, BUTTON_GHOST, BUTTON_PRIMARY, FIELD_LABEL, HINT, INPUT, SELECT, SURFACE, TEXTAREA } from "@/components/ui/primitives";\nimport {\n  createHolidayCalendar, deleteHolidayCalendar, listHolidayCalendars, obligationKeys, updateHolidayCalendar,\n} from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport { WEEKDAY_LABELS, formatDay, type HolidayCalendarCreate, type HolidayRow } from "@/types/obligations";\n\ntype Source = "TEMPLATE" | "MANUAL" | "ICS";\n\n/** "2026-01-26 Republic Day" per line (the name is optional). */\nexport const parseHolidayLines = (text: string): HolidayRow[] => {\n  const out: HolidayRow[] = [];\n  for (const raw of text.split(/\\r?\\n/)) {\n    const m = /^\\s*(\\d{4}-\\d{2}-\\d{2})\\s*[,;:\\t -]?\\s*(.*)$/.exec(raw);\n    if (m && m[1]) {\n      out.push({ date: m[1], name: (m[2] ?? "").trim().slice(0, 120) || "Holiday" });\n    }\n  }\n  return out;\n};\n\ninterface Props {\n  readonly workspaceId: string;\n  readonly isAdmin: boolean;\n}\n\nexport const HolidayCalendars: React.FC<Props> = ({ workspaceId, isAdmin }) => {\n  const queryClient = useQueryClient();\n  const query = useQuery({ queryKey: obligationKeys.calendars(workspaceId), queryFn: () => listHolidayCalendars(workspaceId),\n    enabled: Boolean(workspaceId) });\n  const [name, setName] = useState("");\n  const [source, setSource] = useState<Source>("TEMPLATE");\n  const [template, setTemplate] = useState("IN-NATIONAL");\n  const [years, setYears] = useState(`${new Date().getFullYear()}, ${new Date().getFullYear() + 1}`);\n  const [lines, setLines] = useState("");\n  const [ics, setIcs] = useState("");\n  const [weekend, setWeekend] = useState<number[]>([6, 7]);\n  const [makeDefault, setMakeDefault] = useState(true);\n  const [open, setOpen] = useState<string | null>(null);\n  const [message, setMessage] = useState<string | null>(null);\n  const refresh = (): void => {\n    void queryClient.invalidateQueries({ queryKey: obligationKeys.all(workspaceId) });\n  };\n\n  const create = useMutation({\n    mutationFn: () => {\n      const yearList = years.split(/[\\s,]+/).map((y) => Number.parseInt(y, 10)).filter((y) => !Number.isNaN(y));\n      const body: HolidayCalendarCreate = {\n        name: name.trim(), weekend_days: weekend, is_default: makeDefault,\n        ...(source === "TEMPLATE" ? { template, years: yearList } : {}),\n        ...(source === "MANUAL" ? { holidays: parseHolidayLines(lines) } : {}),\n        ...(source === "ICS" ? { ics, years: yearList } : {}),\n      };\n      return createHolidayCalendar(workspaceId, body);\n    },\n    onSuccess: (row) => { setName(""); setLines(""); setIcs(""); setMessage(`Saved ${row.name} with ${row.holidays.length} holiday(s).`); refresh(); },\n  });\n  const makeDefaultMutation = useMutation({\n    mutationFn: (id: string) => updateHolidayCalendar(workspaceId, id, { is_default: true }),\n    onSuccess: refresh,\n  });\n  const remove = useMutation({\n    mutationFn: (id: string) => deleteHolidayCalendar(workspaceId, id),\n    onSuccess: refresh,\n  });\n\n  const readFile = (file: File | undefined): void => {\n    if (!file) {\n      return;\n    }\n    const reader = new FileReader();\n    reader.onload = () => setIcs(String(reader.result ?? ""));\n    reader.readAsText(file);\n  };\n  const toggleWeekend = (day: number): void => {\n    setWeekend((current) => (current.includes(day) ? current.filter((d) => d !== day) : [...current, day].sort()));\n  };\n\n  return (\n    <div className="space-y-4">\n      <p className={HINT}>\n        Business days skip a calendar&apos;s weekend days and its stored holidays. New obligations use the default calendar;\n        an obligation keeps the calendar it was created with until you change it.\n      </p>\n      {query.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n      {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "Calendars could not be loaded.")}</p> : null}\n      <ul className="space-y-2">\n        {(query.data?.items ?? []).map((cal) => (\n          <li key={cal.id} className={`${SURFACE} space-y-2 p-3`}>\n            <div className="flex flex-wrap items-center gap-2">\n              <CalendarDays className="h-4 w-4 text-muted-foreground" aria-hidden />\n              <span className="font-semibold">{cal.name}</span>\n              {cal.is_default ? <span className="rounded bg-primary/10 px-1.5 py-0.5 text-[10px] font-semibold text-primary">Default</span> : null}\n              <span className={HINT}>\n                {cal.holidays.length} holiday(s) · weekend {cal.weekend_days.map((d) => WEEKDAY_LABELS[d - 1]).join(", ") || "none"}\n                · {cal.obligations} obligation(s) · {cal.source.toLowerCase()}{cal.template_code ? ` ${cal.template_code}` : ""}\n              </span>\n              <button type="button" className={`${BUTTON_GHOST} ml-auto`} onClick={() => setOpen(open === cal.id ? null : cal.id)}>\n                {open === cal.id ? "Hide dates" : "Show dates"}\n              </button>\n              {isAdmin && !cal.is_default ? (\n                <button type="button" className={BUTTON_GHOST} disabled={makeDefaultMutation.isPending}\n                  onClick={() => makeDefaultMutation.mutate(cal.id)}>\n                  <Star className="h-4 w-4" aria-hidden /> Make default\n                </button>\n              ) : null}\n              {isAdmin ? (\n                <button type="button" className={BUTTON_DESTRUCTIVE} disabled={remove.isPending}\n                  onClick={() => { if (window.confirm(`Delete ${cal.name}? Its obligations fall back to weekends only.`)) { remove.mutate(cal.id); } }}>\n                  <Trash2 className="h-4 w-4" aria-hidden /> Delete\n                </button>\n              ) : null}\n            </div>\n            {open === cal.id ? (\n              <ul className="grid gap-x-4 text-xs sm:grid-cols-2 md:grid-cols-3">\n                {cal.holidays.map((h) => (\n                  <li key={h.date}><span className="tabular-nums">{formatDay(h.date)}</span> — {h.name}</li>\n                ))}\n              </ul>\n            ) : null}\n          </li>\n        ))}\n        {query.data && query.data.items.length === 0 ? <li className={HINT}>No holiday calendar yet: business days skip weekends only.</li> : null}\n      </ul>\n      {isAdmin ? (\n        <form className={`${SURFACE} space-y-3 p-4`} aria-label="New holiday calendar"\n          onSubmit={(event) => { event.preventDefault(); if (name.trim()) { create.mutate(); } }}>\n          <h3 className="text-sm font-semibold">New holiday calendar</h3>\n          <div className="grid gap-3 md:grid-cols-2">\n            <label className="space-y-1">\n              <span className={FIELD_LABEL}>Name</span>\n              <input className={INPUT} value={name} maxLength={120} onChange={(e) => setName(e.target.value)} placeholder="India national holidays" />\n            </label>\n            <label className="space-y-1">\n              <span className={FIELD_LABEL}>From</span>\n              <select className={SELECT} value={source} onChange={(e) => setSource(e.target.value as Source)}>\n                <option value="TEMPLATE">A built-in template</option>\n                <option value="MANUAL">Dates I paste</option>\n                <option value="ICS">An .ics file</option>\n              </select>\n            </label>\n          </div>\n          {source === "TEMPLATE" ? (\n            <div className="grid gap-3 md:grid-cols-2">\n              <label className="space-y-1">\n                <span className={FIELD_LABEL}>Template</span>\n                <select className={SELECT} value={template} onChange={(e) => setTemplate(e.target.value)}>\n                  {(query.data?.templates ?? []).map((t) => <option key={t.code} value={t.code}>{t.name}</option>)}\n                </select>\n                <span className={HINT}>{query.data?.templates.find((t) => t.code === template)?.description ?? ""}</span>\n              </label>\n              <label className="space-y-1">\n                <span className={FIELD_LABEL}>Years</span>\n                <input className={INPUT} value={years} onChange={(e) => setYears(e.target.value)} />\n              </label>\n            </div>\n          ) : null}\n          {source === "MANUAL" ? (\n            <label className="block space-y-1">\n              <span className={FIELD_LABEL}>Holidays, one per line</span>\n              <textarea className={TEXTAREA} rows={6} value={lines} onChange={(e) => setLines(e.target.value)}\n                placeholder={"2026-01-26 Republic Day\\n2026-10-20 Diwali"} />\n              <span className={HINT}>{parseHolidayLines(lines).length} date(s) read</span>\n            </label>\n          ) : null}\n          {source === "ICS" ? (\n            <div className="space-y-1">\n              <input type="file" accept=".ics,text/calendar" onChange={(e) => readFile(e.target.files?.[0])} aria-label=".ics file" />\n              <label className="block space-y-1">\n                <span className={HINT}>Years to expand yearly repeats into</span>\n                <input className={INPUT} value={years} onChange={(e) => setYears(e.target.value)} />\n              </label>\n              <span className={HINT}>{ics ? `${ics.length.toLocaleString()} characters loaded` : "No file chosen"}</span>\n            </div>\n          ) : null}\n          <fieldset className="flex flex-wrap items-center gap-2 text-xs">\n            <legend className={FIELD_LABEL}>Weekend days</legend>\n            {WEEKDAY_LABELS.map((label, i) => (\n              <label key={label} className="inline-flex items-center gap-1">\n                <input type="checkbox" checked={weekend.includes(i + 1)} onChange={() => toggleWeekend(i + 1)} /> {label}\n              </label>\n            ))}\n          </fieldset>\n          <label className="inline-flex items-center gap-2 text-sm">\n            <input type="checkbox" checked={makeDefault} onChange={(e) => setMakeDefault(e.target.checked)} /> Use for new obligations\n          </label>\n          {create.isError ? <p className="text-sm text-destructive">{errorMessage(create.error, "The calendar could not be saved.")}</p> : null}\n          {message ? <p className="text-sm text-muted-foreground" aria-live="polite">{message}</p> : null}\n          <button type="submit" className={BUTTON_PRIMARY} disabled={!name.trim() || create.isPending}>\n            {create.isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : null} Save calendar\n          </button>\n        </form>\n      ) : null}\n    </div>\n  );\n};\n\nexport default HolidayCalendars;\n'),
    Op(path='frontend/src/components/obligations/NewObligation.tsx', kind='new', final_sha='f50bb53d1c34f2ab870bb6910648be11dc4a9491d10fbf1d36ec3a379b5826b7',
       variants=(),
       content='/**\n * ARCH46-S2:new-obligation — a person\'s own obligation: a stated date, a date\n * counted from another date ("renewal − 60 days", in days, business days,\n * months or years), or a repeating series (RFC 5545 RRULE). "Check the date"\n * asks the server for the exact arithmetic — month ends, leap years, business\n * days on the chosen holiday calendar — and shows every step before saving.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery } from "@tanstack/react-query";\nimport { Calculator, Loader2 } from "lucide-react";\n\nimport { BUTTON_GHOST, BUTTON_PRIMARY, FIELD_LABEL, HINT, INPUT, SELECT, SURFACE } from "@/components/ui/primitives";\nimport { calculateDate, createObligation, listHolidayCalendars, obligationKeys } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport { listWorkspaceMembers } from "@/services/api/workspaces";\nimport {\n  KINDS, KIND_LABELS, ROLLS, ROLL_LABELS, UNITS, UNIT_LABELS, formatDay,\n  type DateCalculation, type ObligationDetail, type ObligationKind, type RuleSpec,\n} from "@/types/obligations";\n\ntype Mode = "FIXED" | "OFFSET" | "SERIES";\n\nconst SERIES_PRESETS: readonly { readonly label: string; readonly rrule: string }[] = [\n  { label: "Every month", rrule: "FREQ=MONTHLY" },\n  { label: "Last day of every month", rrule: "FREQ=MONTHLY;BYMONTHDAY=-1" },\n  { label: "Every quarter end", rrule: "FREQ=YEARLY;BYMONTH=3,6,9,12;BYMONTHDAY=-1" },\n  { label: "Every year", rrule: "FREQ=YEARLY" },\n  { label: "Every week", rrule: "FREQ=WEEKLY" },\n];\n\ninterface Props {\n  readonly workspaceId: string;\n  readonly onCreated: (detail: ObligationDetail) => void;\n  readonly onCancel: () => void;\n}\n\nexport const NewObligation: React.FC<Props> = ({ workspaceId, onCreated, onCancel }) => {\n  const [kind, setKind] = useState<ObligationKind>("OTHER");\n  const [title, setTitle] = useState("");\n  const [mode, setMode] = useState<Mode>("FIXED");\n  const [date, setDate] = useState("");\n  const [anchorDate, setAnchorDate] = useState("");\n  const [sign, setSign] = useState(-1);\n  const [n, setN] = useState(30);\n  const [unit, setUnit] = useState("DAY");\n  const [rrule, setRrule] = useState(SERIES_PRESETS[0]?.rrule ?? "FREQ=MONTHLY");\n  const [start, setStart] = useState("");\n  const [offsetDays, setOffsetDays] = useState(0);\n  const [roll, setRoll] = useState("NONE");\n  const [owner, setOwner] = useState("");\n  const [calendarId, setCalendarId] = useState("");\n  const [lead, setLead] = useState("");\n  const [preview, setPreview] = useState<DateCalculation | null>(null);\n\n  const members = useQuery({ queryKey: ["workspace-members", workspaceId], queryFn: () => listWorkspaceMembers(workspaceId),\n    enabled: Boolean(workspaceId) });\n  const calendars = useQuery({ queryKey: obligationKeys.calendars(workspaceId), queryFn: () => listHolidayCalendars(workspaceId),\n    enabled: Boolean(workspaceId) });\n\n  const rule = (): RuleSpec => {\n    if (mode === "FIXED") {\n      return { kind: "FIXED", date, roll };\n    }\n    if (mode === "OFFSET") {\n      return { kind: "OFFSET", anchor_date: anchorDate, sign, period: { n, unit }, roll };\n    }\n    const base: RuleSpec = { kind: "SERIES", rrule, start, roll };\n    return offsetDays ? { ...base, sign: 1, period: { n: offsetDays, unit: "DAY" } } : base;\n  };\n\n  const calc = useMutation({\n    mutationFn: () => calculateDate(workspaceId, calendarId ? { rule: rule(), calendar_id: calendarId } : { rule: rule() }),\n    onSuccess: (result) => setPreview(result),\n  });\n  const create = useMutation({\n    mutationFn: () => {\n      const leadDays = lead.trim() ? Number.parseInt(lead, 10) : null;\n      return createObligation(workspaceId, {\n        kind, title: title.trim(), rule: rule(),\n        ...(owner ? { owner_user_id: owner } : {}),\n        ...(calendarId ? { calendar_id: calendarId } : {}),\n        ...(leadDays !== null && !Number.isNaN(leadDays) ? { lead_days: leadDays } : {}),\n      });\n    },\n    onSuccess: onCreated,\n  });\n  const ready = title.trim().length > 0 && (\n    (mode === "FIXED" && date) || (mode === "OFFSET" && anchorDate && n >= 0) || (mode === "SERIES" && start && rrule));\n  const owners = (members.data?.items ?? []).filter((m) => m.id !== null && m.status === "ACTIVE");\n\n  return (\n    <form className={`${SURFACE} space-y-3 p-4`} aria-label="New obligation"\n      onSubmit={(event) => { event.preventDefault(); if (ready) { create.mutate(); } }}>\n      <div className="grid gap-3 md:grid-cols-3">\n        <label className="space-y-1 md:col-span-2">\n          <span className={FIELD_LABEL}>What is due</span>\n          <input className={INPUT} value={title} maxLength={300} onChange={(e) => setTitle(e.target.value)}\n            placeholder="File the annual compliance return" />\n        </label>\n        <label className="space-y-1">\n          <span className={FIELD_LABEL}>Kind</span>\n          <select className={SELECT} value={kind} onChange={(e) => setKind(e.target.value as ObligationKind)}>\n            {KINDS.map((k) => <option key={k} value={k}>{KIND_LABELS[k]}</option>)}\n          </select>\n        </label>\n      </div>\n      <fieldset className="space-y-2">\n        <legend className={FIELD_LABEL}>When</legend>\n        <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="How the date is set">\n          {([["FIXED", "On a date"], ["OFFSET", "Counted from a date"], ["SERIES", "Repeats"]] as const).map(([value, label]) => (\n            <button key={value} type="button" role="radio" aria-checked={mode === value} onClick={() => { setMode(value); setPreview(null); }}\n              className={`rounded-full border px-3 py-1 text-xs font-semibold ${mode === value ? "border-primary bg-primary/10 text-primary" : "border-border text-muted-foreground"}`}>\n              {label}\n            </button>\n          ))}\n        </div>\n        {mode === "FIXED" ? (\n          <input type="date" className={`${INPUT} max-w-xs`} value={date} onChange={(e) => setDate(e.target.value)} aria-label="Due date" />\n        ) : null}\n        {mode === "OFFSET" ? (\n          <div className="flex flex-wrap items-center gap-2 text-sm">\n            <input type="number" min={0} max={3650} className={`${INPUT} w-24`} value={n}\n              onChange={(e) => setN(Number.parseInt(e.target.value || "0", 10))} aria-label="How many" />\n            <select className={`${SELECT} w-40`} value={unit} onChange={(e) => setUnit(e.target.value)} aria-label="Unit">\n              {UNITS.map((u) => <option key={u} value={u}>{UNIT_LABELS[u]}</option>)}\n            </select>\n            <select className={`${SELECT} w-28`} value={sign} onChange={(e) => setSign(Number.parseInt(e.target.value, 10))} aria-label="Before or after">\n              <option value={-1}>before</option>\n              <option value={1}>after</option>\n            </select>\n            <input type="date" className={`${INPUT} w-44`} value={anchorDate} onChange={(e) => setAnchorDate(e.target.value)} aria-label="Anchor date" />\n          </div>\n        ) : null}\n        {mode === "SERIES" ? (\n          <div className="grid gap-2 md:grid-cols-3">\n            <label className="space-y-1">\n              <span className={HINT}>Repeats</span>\n              <select className={SELECT} value={rrule} onChange={(e) => setRrule(e.target.value)}>\n                {SERIES_PRESETS.map((p) => <option key={p.rrule} value={p.rrule}>{p.label}</option>)}\n              </select>\n            </label>\n            <label className="space-y-1">\n              <span className={HINT}>RRULE (RFC 5545)</span>\n              <input className={`${INPUT} font-mono text-xs`} value={rrule} onChange={(e) => setRrule(e.target.value)} />\n            </label>\n            <label className="space-y-1">\n              <span className={HINT}>Starting</span>\n              <input type="date" className={INPUT} value={start} onChange={(e) => setStart(e.target.value)} />\n            </label>\n            <label className="space-y-1">\n              <span className={HINT}>Days after each date</span>\n              <input type="number" min={0} max={365} className={INPUT} value={offsetDays}\n                onChange={(e) => setOffsetDays(Number.parseInt(e.target.value || "0", 10))} />\n            </label>\n          </div>\n        ) : null}\n        <div className="grid gap-2 md:grid-cols-2">\n          <label className="space-y-1">\n            <span className={HINT}>On a weekend or holiday</span>\n            <select className={SELECT} value={roll} onChange={(e) => setRoll(e.target.value)}>\n              {ROLLS.map((r) => <option key={r} value={r}>{ROLL_LABELS[r]}</option>)}\n            </select>\n          </label>\n          <label className="space-y-1">\n            <span className={HINT}>Holiday calendar</span>\n            <select className={SELECT} value={calendarId} onChange={(e) => setCalendarId(e.target.value)}>\n              <option value="">Weekends only</option>\n              {(calendars.data?.items ?? []).map((c) => <option key={c.id} value={c.id}>{c.name}{c.is_default ? " (default)" : ""}</option>)}\n            </select>\n          </label>\n        </div>\n        <button type="button" className={BUTTON_GHOST} disabled={!ready || calc.isPending} onClick={() => calc.mutate()}>\n          {calc.isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : <Calculator className="h-4 w-4" aria-hidden />}\n          Check the date\n        </button>\n        {calc.isError ? <p className="text-sm text-destructive">{errorMessage(calc.error, "That rule could not be read.")}</p> : null}\n        {preview ? (\n          <div className="rounded-lg border border-border/60 bg-muted/30 p-2 text-xs" aria-live="polite">\n            <p className="font-semibold">Due {formatDay(preview.due_date)}</p>\n            <ol className="ml-4 list-decimal text-muted-foreground">\n              {preview.steps.map((step) => <li key={step}>{step}</li>)}\n            </ol>\n            {preview.upcoming.length > 1 ? (\n              <p className="mt-1 text-muted-foreground">Then {preview.upcoming.slice(1, 6).map((o) => formatDay(o.due_date)).join(", ")}</p>\n            ) : null}\n          </div>\n        ) : null}\n      </fieldset>\n      <div className="grid gap-3 md:grid-cols-2">\n        <label className="space-y-1">\n          <span className={FIELD_LABEL}>Owner</span>\n          <select className={SELECT} value={owner} onChange={(e) => setOwner(e.target.value)}>\n            <option value="">Unassigned</option>\n            {owners.map((m) => <option key={m.user.id} value={m.user.id}>{m.user.email}</option>)}\n          </select>\n        </label>\n        <label className="space-y-1">\n          <span className={FIELD_LABEL}>Remind how many days before</span>\n          <input type="number" min={0} max={365} className={INPUT} value={lead} placeholder="Default for the kind"\n            onChange={(e) => setLead(e.target.value)} />\n        </label>\n      </div>\n      {create.isError ? <p className="text-sm text-destructive">{errorMessage(create.error, "The obligation could not be saved.")}</p> : null}\n      <div className="flex gap-2">\n        <button type="submit" className={BUTTON_PRIMARY} disabled={!ready || create.isPending}>\n          {create.isPending ? <Loader2 className="h-4 w-4 animate-spin" aria-hidden /> : null} Save obligation\n        </button>\n        <button type="button" className={BUTTON_GHOST} onClick={onCancel}>Cancel</button>\n      </div>\n    </form>\n  );\n};\n\nexport default NewObligation;\n'),
    Op(path='frontend/src/components/obligations/ObligationCalendar.tsx', kind='new', final_sha='841efbb40f721a2eb8f8fca0f991a38a35b21cf03a2ce1cbc98a4734e1fee903',
       variants=(),
       content='/**\n * ARCH46-S2:obligation-calendar — a month of obligations. Due dates are LOCAL\n * dates in the workspace\'s zone (the server says which day "today" is there),\n * so the grid is built from YYYY-MM-DD strings, never from instants a browser\n * in another zone would shift. Future occurrences of a series are shown too,\n * marked as projected.\n */\nimport React, { useMemo, useState } from "react";\nimport { useQuery } from "@tanstack/react-query";\nimport { Link } from "react-router-dom";\nimport { ChevronLeft, ChevronRight, Loader2 } from "lucide-react";\n\nimport { BUTTON_GHOST, HINT, SURFACE } from "@/components/ui/primitives";\nimport { obligationPath } from "@/routes/tenantPaths";\nimport { getCalendar, obligationKeys } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport { KIND_LABELS, STATE_TONE, WEEKDAY_LABELS, type CalendarOccurrence } from "@/types/obligations";\nimport { formatCalendarMonth } from "@/utils/displayTime";\n\nconst pad = (n: number): string => String(n).padStart(2, "0");\nconst iso = (y: number, m: number, d: number): string => `${y}-${pad(m)}-${pad(d)}`;\n\n/** Day arithmetic on calendar dates (UTC is used only as an arithmetic frame, never shown). */\nconst shiftDay = (value: string, days: number): string => {\n  const [y, m, d] = value.split("-").map((x) => Number.parseInt(x, 10));\n  const t = new Date(Date.UTC(y ?? 1970, (m ?? 1) - 1, (d ?? 1) + days));\n  return iso(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());\n};\n\nconst isoWeekday = (value: string): number => {\n  const [y, m, d] = value.split("-").map((x) => Number.parseInt(x, 10));\n  const w = new Date(Date.UTC(y ?? 1970, (m ?? 1) - 1, d ?? 1)).getUTCDay();\n  return w === 0 ? 7 : w;\n};\n\ninterface Props {\n  readonly workspaceId: string;\n  readonly orgSlug: string;\n  readonly workspaceSlug: string;\n  readonly mine: boolean;\n}\n\nexport const ObligationCalendar: React.FC<Props> = ({ workspaceId, orgSlug, workspaceSlug, mine }) => {\n  const now = new Date();\n  const [month, setMonth] = useState<{ y: number; m: number }>({ y: now.getFullYear(), m: now.getMonth() + 1 });\n  const first = iso(month.y, month.m, 1);\n  const gridStart = shiftDay(first, -(isoWeekday(first) - 1));\n  const gridEnd = shiftDay(gridStart, 41);\n  const owner = mine ? "me" : "";\n  const query = useQuery({\n    queryKey: obligationKeys.calendar(workspaceId, gridStart, gridEnd, owner),\n    queryFn: () => getCalendar(workspaceId, gridStart, gridEnd, owner || undefined),\n    enabled: Boolean(workspaceId),\n  });\n  const byDay = useMemo(() => {\n    const out = new Map<string, CalendarOccurrence[]>();\n    for (const item of query.data?.items ?? []) {\n      const list = out.get(item.due_date) ?? [];\n      list.push(item);\n      out.set(item.due_date, list);\n    }\n    return out;\n  }, [query.data]);\n  const days = Array.from({ length: 42 }, (_, i) => shiftDay(gridStart, i));\n  const today = query.data?.today ?? "";\n  const monthName = formatCalendarMonth(month.y, month.m);\n  const move = (delta: number): void => {\n    const total = month.y * 12 + (month.m - 1) + delta;\n    setMonth({ y: Math.floor(total / 12), m: (total % 12) + 1 });\n  };\n\n  return (\n    <section className={`${SURFACE} space-y-3 p-3`} aria-label="Obligations calendar">\n      <div className="flex flex-wrap items-center gap-2">\n        <button type="button" className={BUTTON_GHOST} onClick={() => move(-1)} aria-label="Previous month">\n          <ChevronLeft className="h-4 w-4" aria-hidden />\n        </button>\n        <h2 className="min-w-40 text-center text-base font-semibold">{monthName}</h2>\n        <button type="button" className={BUTTON_GHOST} onClick={() => move(1)} aria-label="Next month">\n          <ChevronRight className="h-4 w-4" aria-hidden />\n        </button>\n        <button type="button" className={BUTTON_GHOST}\n          onClick={() => setMonth({ y: now.getFullYear(), m: now.getMonth() + 1 })}>This month</button>\n        {query.isFetching ? <Loader2 className="h-4 w-4 animate-spin" aria-label="Loading" /> : null}\n        {query.data ? <span className={`${HINT} ml-auto`}>Dates in {query.data.timezone}</span> : null}\n      </div>\n      {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "The calendar could not be loaded.")}</p> : null}\n      <div className="grid grid-cols-7 gap-px overflow-hidden rounded-lg border border-border/60 bg-border/60 text-xs" role="grid">\n        {WEEKDAY_LABELS.map((label) => (\n          <div key={label} className="bg-muted/60 p-1.5 text-center font-semibold text-muted-foreground" role="columnheader">{label}</div>\n        ))}\n        {days.map((day) => {\n          const inMonth = day.slice(0, 7) === first.slice(0, 7);\n          const items = byDay.get(day) ?? [];\n          return (\n            <div key={day} role="gridcell" aria-label={day}\n              className={`min-h-24 space-y-1 bg-card p-1.5 ${inMonth ? "" : "opacity-50"} ${day === today ? "ring-2 ring-inset ring-primary" : ""}`}>\n              <div className={`text-right tabular-nums ${day === today ? "font-bold text-primary" : "text-muted-foreground"}`}>\n                {Number.parseInt(day.slice(8), 10)}\n              </div>\n              {items.slice(0, 4).map((item) => (\n                <Link key={`${item.obligation_id}-${item.occurrence}`} to={obligationPath(orgSlug, workspaceSlug, item.obligation_id)}\n                  title={`${KIND_LABELS[item.kind]}: ${item.title}${item.projected ? " (a later occurrence)" : ""}`}\n                  className={`block truncate rounded px-1 py-0.5 ${STATE_TONE[item.state]} ${item.projected ? "border border-dashed border-border bg-transparent" : ""}`}>\n                  {item.title}\n                </Link>\n              ))}\n              {items.length > 4 ? <div className="text-[10px] text-muted-foreground">+{items.length - 4} more</div> : null}\n            </div>\n          );\n        })}\n      </div>\n    </section>\n  );\n};\n\nexport default ObligationCalendar;\n'),
    Op(path='frontend/src/components/obligations/ObligationTable.tsx', kind='new', final_sha='5036d1585e55c48070174964f1a2fdbf3dbbe6811ec1647a035b26d3cc690a59',
       variants=(),
       content='/**\n * ARCH46-S2:obligation-table — obligations as rows: when each is due (in the\n * workspace\'s local dates), what it is, who owns it, the party (its ARCH-42\n * record when resolved) and the document it was read from. Shared by the\n * Obligations page, Work Item details and Entity 360.\n */\nimport React from "react";\nimport { Link } from "react-router-dom";\nimport { Repeat } from "lucide-react";\n\nimport { SCROLL_X, TABLE_HEAD, TABLE_ROW } from "@/components/ui/primitives";\nimport { entityPath, obligationPath, workItemDetailsPath } from "@/routes/tenantPaths";\nimport {\n  KIND_LABELS, REVIEW_LABELS, STATE_LABELS, STATE_TONE, dueLabel, formatDay, type ObligationRow,\n} from "@/types/obligations";\n\ninterface Props {\n  readonly rows: readonly ObligationRow[];\n  readonly orgSlug: string;\n  readonly workspaceSlug: string;\n  readonly hideDocument?: boolean;\n  readonly hideParty?: boolean;\n  readonly empty?: string;\n}\n\nexport const ObligationTable: React.FC<Props> = ({ rows, orgSlug, workspaceSlug, hideDocument, hideParty, empty }) => (\n  <div className={SCROLL_X}>\n    <table className="w-full text-sm">\n      <thead>\n        <tr className={TABLE_HEAD}>\n          <th className="p-2">Due</th>\n          <th className="p-2">Obligation</th>\n          <th className="p-2">Owner</th>\n          {hideParty ? null : <th className="p-2">Party</th>}\n          {hideDocument ? null : <th className="p-2">Document</th>}\n          <th className="p-2">State</th>\n        </tr>\n      </thead>\n      <tbody>\n        {rows.map((row) => (\n          <tr key={row.id} className={`${TABLE_ROW} ${row.superseded ? "opacity-60" : ""}`}>\n            <td className="whitespace-nowrap p-2 align-top">\n              <div className="font-medium tabular-nums">{formatDay(row.due_date)}</div>\n              <div className={`text-[11px] ${row.state === "OVERDUE" ? "text-destructive" : "text-muted-foreground"}`}>\n                {dueLabel(row)}\n              </div>\n            </td>\n            <td className="p-2 align-top">\n              <Link className="font-medium hover:underline" to={obligationPath(orgSlug, workspaceSlug, row.id)}>\n                {row.title}\n              </Link>\n              <div className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[11px] text-muted-foreground">\n                <span className="rounded bg-muted px-1.5 py-0.5 font-semibold">{KIND_LABELS[row.kind]}</span>\n                {row.recurrence_text ? (\n                  <span className="inline-flex items-center gap-1">\n                    <Repeat className="h-3 w-3" aria-hidden /> {row.recurrence_text}\n                  </span>\n                ) : null}\n                {row.review === "PENDING" ? (\n                  <span className="rounded bg-amber-500/15 px-1.5 py-0.5 font-semibold text-amber-700 dark:text-amber-300"\n                    title={row.reasons.join("; ")}>\n                    {REVIEW_LABELS.PENDING}\n                  </span>\n                ) : null}\n                {row.review === "REJECTED" ? <span className="line-through">{REVIEW_LABELS.REJECTED}</span> : null}\n                {row.superseded ? <span>no longer in the document</span> : null}\n              </div>\n            </td>\n            <td className="p-2 align-top text-xs">{row.owner_email ?? <span className="text-muted-foreground">Unassigned</span>}</td>\n            {hideParty ? null : (\n              <td className="p-2 align-top text-xs">\n                {row.entity_root_id ? (\n                  <Link className="hover:underline" to={entityPath(orgSlug, workspaceSlug, row.entity_root_id)}>\n                    {row.entity_name ?? row.counterparty_name ?? "Record"}\n                  </Link>\n                ) : (\n                  row.counterparty_name ?? <span className="text-muted-foreground">—</span>\n                )}\n              </td>\n            )}\n            {hideDocument ? null : (\n              <td className="p-2 align-top text-xs">\n                {row.work_item_id ? (\n                  <Link className="hover:underline" to={workItemDetailsPath(orgSlug, workspaceSlug, row.work_item_id)}>\n                    {row.work_item_filename ?? "Document"}\n                  </Link>\n                ) : (\n                  <span className="text-muted-foreground">Added by hand</span>\n                )}\n              </td>\n            )}\n            <td className="p-2 align-top">\n              <span className={`rounded px-2 py-0.5 text-xs font-semibold ${STATE_TONE[row.state]}`}>{STATE_LABELS[row.state]}</span>\n            </td>\n          </tr>\n        ))}\n        {rows.length === 0 ? (\n          <tr>\n            <td colSpan={6} className="p-4 text-center text-muted-foreground">{empty ?? "No obligations."}</td>\n          </tr>\n        ) : null}\n      </tbody>\n    </table>\n  </div>\n);\n\nexport default ObligationTable;\n'),
    Op(path='frontend/src/components/review/ResolvePanel.tsx', kind='edit', final_sha='ba75ca85e4a6ec53401ab33209c3a05968349ae71e972c75e17163bbb2e97184',
       variants=(('ad09a14fc7feca8c686dd0470c26e770c91819e26083e536fac9d5f6629f35c4', (('  // material difference at once.\n  if (item.kind === "CORROBORATION") {\n', '  // material difference at once.\n  // ARCH46-S2:resolve-obligation\n  if (item.kind === "OBLIGATION") {\n    return (\n      <div className="space-y-3">\n        <p className="text-sm font-semibold">{item.headline}</p>\n        <p className="text-xs text-muted-foreground">\n          The date was read with a doubt (the reason is on the obligation). Confirm it and its due-soon and overdue\n          alerts reach your flows; reject it and it leaves every list and calendar feed. To correct the date first,{" "}\n          <Link className="underline" to={obligationPath(orgSlug, workspaceSlug, item.item_id)}>open the obligation</Link>.\n        </p>\n        <div className="flex flex-wrap items-center gap-2">\n          <button\n            type="button"\n            disabled={pending}\n            onClick={() => onResolve({ obligation_verdict: "CONFIRM" })}\n            className="rounded-lg bg-primary px-3 py-2 text-sm font-bold text-primary-foreground hover:bg-primary/90 disabled:opacity-50"\n          >\n            Confirm obligation\n          </button>\n          <button\n            type="button"\n            disabled={pending}\n            onClick={() => onResolve({ obligation_verdict: "REJECT" })}\n            className="rounded-lg border border-border px-3 py-2 text-sm font-bold hover:bg-muted disabled:opacity-50"\n          >\n            Not an obligation\n          </button>\n          {pending && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}\n          <button type="button" onClick={onCancel} className="ml-auto rounded-lg px-3 py-2 text-sm text-muted-foreground hover:bg-muted">\n            Cancel\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  if (item.kind === "CORROBORATION") {\n'), ('\nimport { corroborationPath, tablePath } from "@/routes/tenantPaths";\n\n', '\nimport { corroborationPath, obligationPath, tablePath } from "@/routes/tenantPaths";\n\n'))),),
       content=''),
