    Op(path='frontend/src/pages/obligations/ObligationDetail.tsx', kind='new', final_sha='d1474dabfa2915606dad3294ad8d48d65bbde8f4e364bf7e5ce4c4d1b300d351',
       variants=(),
       content='/**\n * ARCH46-S2:page-obligation — one obligation: when it is due and exactly how\n * that date was computed (every step: the stated date, the anchor, the\n * period, month-end clamping, the business-day roll), the clause it was read\n * from (page and quote), what counts from it, its next occurrences, and its\n * history -- including each due-soon and overdue alert and whether Flow\n * Builder was told. Contributors complete, waive, reopen, confirm or reject\n * it, reassign it and correct its date.\n */\nimport React, { useState } from "react";\nimport { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";\nimport { Link, useNavigate, useParams } from "react-router-dom";\nimport { ArrowLeft, Check, CheckCircle2, Loader2, Lock, RotateCcw, Trash2, XCircle } from "lucide-react";\n\nimport { CAPABILITY } from "@/constants/capabilities";\nimport {\n  BUTTON_DESTRUCTIVE, BUTTON_GHOST, BUTTON_PRIMARY, BUTTON_SECONDARY, FIELD_LABEL, HINT, INPUT, PAGE_TITLE, SECTION_TITLE,\n  SELECT, SURFACE,\n} from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { entityPath, obligationPath, obligationsPath, workItemDetailsPath } from "@/routes/tenantPaths";\nimport {\n  completeObligation, deleteObligation, getObligation, obligationKeys, reopenObligation, reviewObligation,\n  updateObligation, waiveObligation,\n} from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport { listWorkspaceMembers } from "@/services/api/workspaces";\nimport {\n  KIND_LABELS, REVIEW_LABELS, ROLLS, ROLL_LABELS, STATE_LABELS, STATE_TONE, dueLabel, formatDay,\n  type ObligationDetail as Detail, type ObligationUpdate,\n} from "@/types/obligations";\nimport { formatDateTime } from "@/utils/formatters";\n\nconst EVENT_LABELS: Readonly<Record<string, string>> = {\n  CREATED: "Created", UPDATED: "Edited", DUE_SOON: "Became due soon", OVERDUE: "Became overdue", REOPENED: "Reopened",\n  DONE: "Marked done", WAIVED: "Waived", ADVANCED: "Occurrence done; next one due", RESCHEDULED: "Due date moved",\n  CONFIRMED: "Confirmed by a reviewer", REJECTED: "Rejected by a reviewer", SUPERSEDED: "No longer in the document",\n};\n\nconst ObligationDetail: React.FC = () => {\n  const { obligationId = "", orgSlug = "", workspaceSlug = "" } = useParams<{ obligationId: string; orgSlug: string; workspaceSlug: string }>();\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.obligations);\n  const role = workspace?.role;\n  const canEdit = role === "ADMIN" || role === "OWNER" || role === "CONTRIBUTOR";\n  const queryClient = useQueryClient();\n  const navigate = useNavigate();\n  const [waiveReason, setWaiveReason] = useState("");\n  const [note, setNote] = useState("");\n  const [newDate, setNewDate] = useState("");\n  const [newRoll, setNewRoll] = useState("");\n  const query = useQuery({\n    queryKey: obligationKeys.detail(workspaceId, obligationId),\n    queryFn: () => getObligation(workspaceId, obligationId),\n    enabled: Boolean(workspaceId && obligationId && capability.granted),\n  });\n  const members = useQuery({ queryKey: ["workspace-members", workspaceId], queryFn: () => listWorkspaceMembers(workspaceId),\n    enabled: Boolean(workspaceId && canEdit && capability.granted) });\n  const done = (detail: Detail): void => {\n    queryClient.setQueryData(obligationKeys.detail(workspaceId, obligationId), detail);\n    void queryClient.invalidateQueries({ queryKey: obligationKeys.all(workspaceId) });\n  };\n  const complete = useMutation({ mutationFn: () => completeObligation(workspaceId, obligationId, note.trim() || undefined),\n    onSuccess: (d) => { setNote(""); done(d); } });\n  const waive = useMutation({ mutationFn: () => waiveObligation(workspaceId, obligationId, waiveReason.trim()),\n    onSuccess: (d) => { setWaiveReason(""); done(d); } });\n  const reopen = useMutation({ mutationFn: () => reopenObligation(workspaceId, obligationId), onSuccess: done });\n  const review = useMutation({ mutationFn: (verdict: "CONFIRM" | "REJECT") => reviewObligation(workspaceId, obligationId, verdict),\n    onSuccess: done });\n  const edit = useMutation({ mutationFn: (body: ObligationUpdate) => updateObligation(workspaceId, obligationId, body),\n    onSuccess: (d) => { setNewDate(""); done(d); } });\n  const remove = useMutation({ mutationFn: () => deleteObligation(workspaceId, obligationId),\n    onSuccess: () => { void queryClient.invalidateQueries({ queryKey: obligationKeys.all(workspaceId) }); navigate(obligationsPath(orgSlug, workspaceSlug)); } });\n  const busy = complete.isPending || waive.isPending || reopen.isPending || review.isPending || edit.isPending || remove.isPending;\n  const failure = [complete, waive, reopen, review, edit, remove].find((m) => m.isError)?.error;\n\n  if (!capability.granted) {\n    return (\n      <p className="m-6 flex items-center gap-2 text-sm text-muted-foreground">\n        <Lock className="h-4 w-4" aria-hidden /> Obligations are included on the Business and Enterprise plans.\n      </p>\n    );\n  }\n  if (query.isLoading) {\n    return <Loader2 className="m-6 h-5 w-5 animate-spin" aria-label="Loading" />;\n  }\n  if (query.isError || !query.data) {\n    return <p className="m-6 text-sm text-destructive">{errorMessage(query.error, "This obligation could not be loaded.")}</p>;\n  }\n  const d = query.data;\n  const o = d.obligation;\n  const closed = o.state === "DONE" || o.state === "WAIVED";\n  const actionable = canEdit && !o.superseded && o.review !== "REJECTED";\n  const owners = (members.data?.items ?? []).filter((m) => m.id !== null && m.status === "ACTIVE");\n\n  return (\n    <div className="space-y-4 p-4">\n      <Link to={obligationsPath(orgSlug, workspaceSlug)} className={`${BUTTON_GHOST} -ml-2`}>\n        <ArrowLeft className="h-4 w-4" aria-hidden /> Obligations\n      </Link>\n      <header className="space-y-1">\n        <div className="flex flex-wrap items-center gap-2">\n          <h1 className={PAGE_TITLE}>{o.title}</h1>\n          <span className={`rounded px-2 py-0.5 text-xs font-semibold ${STATE_TONE[o.state]}`}>{STATE_LABELS[o.state]}</span>\n          <span className="rounded bg-muted px-2 py-0.5 text-xs font-semibold">{KIND_LABELS[o.kind]}</span>\n          {o.review === "PENDING" || o.review === "REJECTED" ? (\n            <span className="rounded bg-amber-500/15 px-2 py-0.5 text-xs font-semibold text-amber-700 dark:text-amber-300">{REVIEW_LABELS[o.review]}</span>\n          ) : null}\n        </div>\n        <p className="text-sm">\n          Due <span className="font-semibold">{formatDay(o.due_date)}</span>\n          {o.due_date ? <span className="text-muted-foreground"> · {dueLabel(o)}</span> : null}\n          {o.recurrence_text ? <span className="text-muted-foreground"> · repeats {o.recurrence_text} (occurrence {o.occurrence})</span> : null}\n          <span className="text-muted-foreground"> · reminder {o.lead_days} day(s) before · {d.timezone}</span>\n        </p>\n        {o.superseded ? <p className="text-sm text-muted-foreground">The document no longer states this obligation (it was reprocessed).</p> : null}\n      </header>\n      {o.reasons.length > 0 && o.review === "PENDING" ? (\n        <div className="rounded-lg border border-amber-500/40 bg-amber-500/10 p-3 text-sm">\n          <p className="font-semibold">Why this needs a person</p>\n          <ul className="ml-4 list-disc">{o.reasons.map((r) => <li key={r}>{r}</li>)}</ul>\n        </div>\n      ) : null}\n      {failure ? <p className="text-sm text-destructive">{errorMessage(failure, "That did not work.")}</p> : null}\n      {actionable ? (\n        <section className={`${SURFACE} space-y-3 p-4`} aria-label="Actions">\n          {o.review === "PENDING" ? (\n            <div className="flex flex-wrap items-center gap-2">\n              <button type="button" className={BUTTON_PRIMARY} disabled={busy || !o.due_date} onClick={() => review.mutate("CONFIRM")}>\n                <Check className="h-4 w-4" aria-hidden /> Confirm\n              </button>\n              <button type="button" className={BUTTON_SECONDARY} disabled={busy} onClick={() => review.mutate("REJECT")}>\n                <XCircle className="h-4 w-4" aria-hidden /> Not an obligation\n              </button>\n              {!o.due_date ? <span className={HINT}>Set the due date below before confirming.</span> : null}\n            </div>\n          ) : null}\n          {closed ? (\n            <button type="button" className={BUTTON_SECONDARY} disabled={busy} onClick={() => reopen.mutate()}>\n              <RotateCcw className="h-4 w-4" aria-hidden /> Reopen\n            </button>\n          ) : (\n            <div className="grid gap-3 md:grid-cols-2">\n              <div className="space-y-1">\n                <input className={INPUT} value={note} maxLength={2000} onChange={(e) => setNote(e.target.value)}\n                  placeholder="Note (optional): notice sent by courier on 2 Nov" aria-label="Completion note" />\n                <button type="button" className={BUTTON_PRIMARY} disabled={busy || !o.due_date} onClick={() => complete.mutate()}>\n                  <CheckCircle2 className="h-4 w-4" aria-hidden /> {o.recurrence ? "Done — move to the next occurrence" : "Mark done"}\n                </button>\n              </div>\n              <div className="space-y-1">\n                <input className={INPUT} value={waiveReason} maxLength={2000} onChange={(e) => setWaiveReason(e.target.value)}\n                  placeholder="Why it no longer applies" aria-label="Waiver reason" />\n                <button type="button" className={BUTTON_SECONDARY} disabled={busy || !waiveReason.trim()} onClick={() => waive.mutate()}>\n                  Waive\n                </button>\n              </div>\n            </div>\n          )}\n          <div className="grid gap-3 md:grid-cols-3">\n            <label className="space-y-1">\n              <span className={FIELD_LABEL}>Owner</span>\n              <select className={SELECT} value={o.owner_user_id ?? ""} disabled={busy}\n                onChange={(e) => edit.mutate({ owner_user_id: e.target.value || null })}>\n                <option value="">Unassigned</option>\n                {owners.map((m) => <option key={m.user.id} value={m.user.id}>{m.user.email}</option>)}\n              </select>\n            </label>\n            <label className="space-y-1">\n              <span className={FIELD_LABEL}>Correct the due date</span>\n              <input type="date" className={INPUT} value={newDate} onChange={(e) => setNewDate(e.target.value)} />\n            </label>\n            <label className="space-y-1">\n              <span className={FIELD_LABEL}>On a weekend or holiday</span>\n              <select className={SELECT} value={newRoll || o.business_day_rule} onChange={(e) => setNewRoll(e.target.value)}>\n                {ROLLS.map((r) => <option key={r} value={r}>{ROLL_LABELS[r]}</option>)}\n              </select>\n            </label>\n          </div>\n          <div className="flex flex-wrap gap-2">\n            <button type="button" className={BUTTON_SECONDARY} disabled={busy || (!newDate && !newRoll)}\n              onClick={() => edit.mutate(newDate\n                ? { due_date: newDate, ...(newRoll ? { business_day_rule: newRoll } : {}) }\n                : { business_day_rule: newRoll })}>\n              Save date\n            </button>\n            {o.origin === "MANUAL" ? (\n              <button type="button" className={`${BUTTON_DESTRUCTIVE} ml-auto`} disabled={busy}\n                onClick={() => { if (window.confirm("Delete this obligation?")) { remove.mutate(); } }}>\n                <Trash2 className="h-4 w-4" aria-hidden /> Delete\n              </button>\n            ) : null}\n          </div>\n        </section>\n      ) : null}\n      <div className="grid gap-4 lg:grid-cols-2">\n        <section className={`${SURFACE} space-y-2 p-4`} aria-label="How the date was computed">\n          <h2 className={SECTION_TITLE}>How the date was computed</h2>\n          <ol className="ml-4 list-decimal space-y-0.5 text-sm">\n            {d.derivation.map((step) => <li key={step}>{step}</li>)}\n          </ol>\n          <p className={HINT}>\n            Business days on {d.calendar_name ?? "weekends only"} · on a non-business day: {ROLL_LABELS[o.business_day_rule]}\n            {d.engine_version ? ` · read by ${d.engine_version}` : ""}\n          </p>\n          {d.anchor ? (\n            <p className="text-sm">Counts from{" "}\n              <Link className="underline" to={obligationPath(orgSlug, workspaceSlug, d.anchor.id)}>{d.anchor.title}</Link>\n              {" "}({formatDay(d.anchor.due_date)})</p>\n          ) : null}\n          {d.dependents.length > 0 ? (\n            <div className="text-sm">\n              <p className="font-semibold">Counting from this</p>\n              <ul className="ml-4 list-disc">\n                {d.dependents.map((x) => (\n                  <li key={x.id}><Link className="underline" to={obligationPath(orgSlug, workspaceSlug, x.id)}>{x.title}</Link> — {formatDay(x.due_date)}</li>\n                ))}\n              </ul>\n            </div>\n          ) : null}\n          {d.upcoming.length > 0 ? (\n            <p className="text-sm">Next occurrences: {d.upcoming.map((u) => formatDay(u.due_date)).join(", ")}</p>\n          ) : null}\n        </section>\n        <section className={`${SURFACE} space-y-2 p-4`} aria-label="Where it comes from">\n          <h2 className={SECTION_TITLE}>Where it comes from</h2>\n          {o.work_item_id ? (\n            <p className="text-sm">\n              <Link className="underline" to={workItemDetailsPath(orgSlug, workspaceSlug, o.work_item_id)}>{o.work_item_filename ?? "The document"}</Link>\n              {d.clause_number ? `, clause ${d.clause_number}` : ""}\n              {d.evidence.length > 0 ? `, page ${d.evidence.map((e) => e.page).filter((p, i, a) => a.indexOf(p) === i).join(", ")}` : ""}\n            </p>\n          ) : <p className="text-sm text-muted-foreground">Added by hand.</p>}\n          {d.quote ? <blockquote className="border-l-2 border-primary/50 pl-3 text-sm italic">{d.quote}</blockquote> : null}\n          {o.entity_root_id ? (\n            <p className="text-sm">Party:{" "}\n              <Link className="underline" to={entityPath(orgSlug, workspaceSlug, o.entity_root_id)}>{o.entity_name ?? o.counterparty_name}</Link>\n            </p>\n          ) : o.counterparty_name ? <p className="text-sm">Party: {o.counterparty_name}</p> : null}\n          {o.amount ? <p className="text-sm">Amount: {o.currency ?? ""} {o.amount}</p> : null}\n          <p className={HINT}>Confidence {Math.round(o.confidence * 100)}% · {REVIEW_LABELS[o.review]}</p>\n          {d.description ? <p className="whitespace-pre-wrap text-sm">{d.description}</p> : null}\n        </section>\n      </div>\n      <section className={`${SURFACE} space-y-2 p-4`} aria-label="History">\n        <h2 className={SECTION_TITLE}>History</h2>\n        <ol className="space-y-1 text-sm">\n          {d.events.map((e) => (\n            <li key={e.id} className="flex flex-wrap gap-2">\n              <span className="text-xs tabular-nums text-muted-foreground">{formatDateTime(e.created_at)}</span>\n              <span>{EVENT_LABELS[e.kind] ?? e.kind}</span>\n              {e.due_date && (e.kind === "DUE_SOON" || e.kind === "OVERDUE") ? <span className={HINT}>for {formatDay(e.due_date)}</span> : null}\n              {e.emitted ? <span className="rounded bg-primary/10 px-1.5 text-[10px] font-semibold text-primary">Flow Builder told</span> : null}\n              {typeof e.detail.note === "string" && e.detail.note ? <span className={HINT}>“{e.detail.note}”</span> : null}\n              {typeof e.detail.reason === "string" && e.detail.reason ? <span className={HINT}>{e.detail.reason}</span> : null}\n            </li>\n          ))}\n        </ol>\n      </section>\n    </div>\n  );\n};\n\nexport default ObligationDetail;\n'),
    Op(path='frontend/src/pages/obligations/Obligations.tsx', kind='new', final_sha='ea9ca80d155ef1922502694f3bb01d223987670b8a0e5646c8584ff207ed2583',
       variants=(),
       content='/**\n * ARCH46-S2:page-obligations — the workspace\'s obligations: a list (filter by\n * state, kind and owner, search, export .ics / .csv), a month calendar, the\n * holiday calendars business days are counted on, and subscribable calendar\n * feeds. Obligations read from documents arrive by themselves after a\n * document is processed; "New obligation" adds a person\'s own. Opening this\n * page with ?entity=<record id> shows one record\'s obligations.\n */\nimport React, { useState } from "react";\nimport { useQuery } from "@tanstack/react-query";\nimport { Link, useNavigate, useParams, useSearchParams } from "react-router-dom";\nimport { CalendarClock, Download, Loader2, Lock, Plus } from "lucide-react";\n\nimport CalendarFeeds from "@/components/obligations/CalendarFeeds";\nimport HolidayCalendars from "@/components/obligations/HolidayCalendars";\nimport NewObligation from "@/components/obligations/NewObligation";\nimport ObligationCalendar from "@/components/obligations/ObligationCalendar";\nimport ObligationTable from "@/components/obligations/ObligationTable";\nimport { CAPABILITY } from "@/constants/capabilities";\nimport { BUTTON_GHOST, BUTTON_PRIMARY, HINT, INPUT, PAGE_TITLE, SECTION_TITLE, SELECT, SURFACE } from "@/components/ui/primitives";\nimport { useActiveWorkspace } from "@/hooks/useActiveWorkspace";\nimport { useCapabilityAccess } from "@/hooks/useCapabilityAccess";\nimport { obligationPath, verificationPath } from "@/routes/tenantPaths";\nimport { downloadObligations, listObligations, obligationKeys, type ObligationFilters } from "@/services/api/obligations";\nimport { errorMessage } from "@/services/api/errors";\nimport { KINDS, KIND_LABELS, STATE_LABELS, type ObligationDetail, type ObligationState } from "@/types/obligations";\n\ntype Tab = "list" | "calendar" | "holidays" | "feeds";\n\nconst STATE_FILTERS: readonly { readonly id: string; readonly label: string }[] = [\n  { id: "OPEN,DUE_SOON,OVERDUE", label: "Open" },\n  { id: "DUE_SOON", label: STATE_LABELS.DUE_SOON },\n  { id: "OVERDUE", label: STATE_LABELS.OVERDUE },\n  { id: "DONE,WAIVED", label: "Closed" },\n  { id: "", label: "All" },\n];\n\nconst Obligations: React.FC = () => {\n  const workspace = useActiveWorkspace();\n  const workspaceId = workspace?.workspaceId ?? "";\n  const { orgSlug = "", workspaceSlug = "" } = useParams<{ orgSlug: string; workspaceSlug: string }>();\n  const navigate = useNavigate();\n  const [params, setParams] = useSearchParams();\n  const entity = params.get("entity") ?? "";\n  const capability = useCapabilityAccess(workspace?.organizationId ?? "", CAPABILITY.obligations);\n  const role = workspace?.role;\n  const canEdit = role === "ADMIN" || role === "OWNER" || role === "CONTRIBUTOR";\n  const isAdmin = role === "ADMIN" || role === "OWNER";\n  const [tab, setTab] = useState<Tab>("list");\n  const [state, setState] = useState("OPEN,DUE_SOON,OVERDUE");\n  const [kind, setKind] = useState("");\n  const [mine, setMine] = useState(false);\n  const [q, setQ] = useState("");\n  const [composing, setComposing] = useState(false);\n  const filters: ObligationFilters = {\n    ...(state ? { state } : {}), ...(kind ? { kind } : {}), ...(mine ? { owner: "me" } : {}),\n    ...(q.trim() ? { q: q.trim() } : {}), ...(entity ? { entity_id: entity } : {}),\n  };\n  const query = useQuery({\n    queryKey: obligationKeys.list(workspaceId, filters),\n    queryFn: () => listObligations(workspaceId, filters),\n    enabled: Boolean(workspaceId && capability.granted && tab === "list"),\n  });\n  const created = (detail: ObligationDetail): void => {\n    setComposing(false);\n    navigate(obligationPath(orgSlug, workspaceSlug, detail.obligation.id));\n  };\n\n  if (!capability.granted) {\n    return (\n      <section className={`${SURFACE} mx-auto mt-6 max-w-2xl space-y-3 p-6`} aria-labelledby="obligations-lock">\n        <div className="flex items-center gap-2">\n          <Lock className="h-4 w-4" aria-hidden />\n          <h2 id="obligations-lock" className={SECTION_TITLE}>Obligations</h2>\n        </div>\n        <p className="text-sm text-muted-foreground">\n          Every renewal date, notice deadline, payment, delivery, expiry and report your documents commit you to — read\n          from the documents, counted in business days on your own holiday calendars, owned by a person, with reminders\n          before they are due, Flow Builder triggers when they are due soon or overdue, and a calendar feed for your\n          calendar app.\n        </p>\n        <p className={HINT}>It&apos;s included on the Business and Enterprise plans.</p>\n      </section>\n    );\n  }\n  const counts = query.data?.counts_by_state ?? {};\n  return (\n    <div className="space-y-4 p-4">\n      <header className="flex flex-wrap items-center gap-2">\n        <CalendarClock className="h-5 w-5" aria-hidden />\n        <h1 className={PAGE_TITLE}>Obligations</h1>\n        {query.data ? <span className={HINT}>Today is {query.data.today} in {query.data.timezone}</span> : null}\n        <div className="ml-auto flex flex-wrap gap-2">\n          <button type="button" className={BUTTON_GHOST} onClick={() => void downloadObligations(workspaceId, "ics")}>\n            <Download className="h-4 w-4" aria-hidden /> .ics\n          </button>\n          <button type="button" className={BUTTON_GHOST} onClick={() => void downloadObligations(workspaceId, "csv")}>\n            <Download className="h-4 w-4" aria-hidden /> .csv\n          </button>\n          {canEdit && !composing ? (\n            <button type="button" className={BUTTON_PRIMARY} onClick={() => setComposing(true)}>\n              <Plus className="h-4 w-4" aria-hidden /> New obligation\n            </button>\n          ) : null}\n        </div>\n      </header>\n      {query.data && query.data.pending_review > 0 ? (\n        <p className="rounded-lg border border-amber-500/40 bg-amber-500/10 p-2 text-sm">\n          {query.data.pending_review} obligation(s) were read with a doubt and wait for a person to confirm them.{" "}\n          <Link className="font-semibold underline" to={verificationPath(orgSlug, workspaceSlug)}>Open the review hub</Link>\n        </p>\n      ) : null}\n      {composing ? <NewObligation workspaceId={workspaceId} onCreated={created} onCancel={() => setComposing(false)} /> : null}\n      <div className="flex flex-wrap gap-2 border-b border-border/60" role="tablist" aria-label="Obligations views">\n        {([["list", "List"], ["calendar", "Calendar"], ["holidays", "Holiday calendars"], ["feeds", "Calendar feeds"]] as const)\n          .map(([id, label]) => (\n            <button key={id} type="button" role="tab" aria-selected={tab === id} onClick={() => setTab(id)}\n              className={`border-b-2 px-3 py-2 text-sm font-semibold ${tab === id ? "border-primary text-primary" : "border-transparent text-muted-foreground hover:text-foreground"}`}>\n              {label}\n            </button>\n          ))}\n      </div>\n      {tab === "list" ? (\n        <div className="space-y-3">\n          {entity ? (\n            <p className="text-sm">\n              Showing one record&apos;s obligations.{" "}\n              <button type="button" className="font-semibold text-primary hover:underline"\n                onClick={() => { params.delete("entity"); setParams(params, { replace: true }); }}>Show all</button>\n            </p>\n          ) : null}\n          <div className="flex flex-wrap items-center gap-2">\n            {STATE_FILTERS.map((f) => (\n              <button key={f.label} type="button" aria-pressed={state === f.id} onClick={() => setState(f.id)}\n                className={`rounded-full border px-3 py-1 text-xs font-semibold ${state === f.id ? "border-primary bg-primary/10 text-primary" : "border-border text-muted-foreground hover:bg-muted"}`}>\n                {f.label}\n                {f.id && !f.id.includes(",") ? ` (${counts[f.id as ObligationState] ?? 0})` : ""}\n              </button>\n            ))}\n            <select className={`${SELECT} w-44`} value={kind} onChange={(e) => setKind(e.target.value)} aria-label="Kind">\n              <option value="">Every kind</option>\n              {KINDS.map((k) => <option key={k} value={k}>{KIND_LABELS[k]}</option>)}\n            </select>\n            <label className="inline-flex items-center gap-1 text-sm">\n              <input type="checkbox" checked={mine} onChange={(e) => setMine(e.target.checked)} /> Mine\n            </label>\n            <input className={`${INPUT} w-56`} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search title or party"\n              aria-label="Search" />\n          </div>\n          {query.isLoading ? <Loader2 className="h-5 w-5 animate-spin" aria-label="Loading" /> : null}\n          {query.isError ? <p className="text-sm text-destructive">{errorMessage(query.error, "Obligations could not be loaded.")}</p> : null}\n          {query.data ? (\n            <div className={SURFACE}>\n              <ObligationTable rows={query.data.items} orgSlug={orgSlug} workspaceSlug={workspaceSlug}\n                empty="No obligations match. Obligations are read from documents as they are processed." />\n              {query.data.total > query.data.items.length ? (\n                <p className={`${HINT} p-2`}>Showing {query.data.items.length} of {query.data.total}; narrow the filters to see the rest.</p>\n              ) : null}\n            </div>\n          ) : null}\n        </div>\n      ) : null}\n      {tab === "calendar" ? (\n        <div className="space-y-2">\n          <label className="inline-flex items-center gap-1 text-sm">\n            <input type="checkbox" checked={mine} onChange={(e) => setMine(e.target.checked)} /> Only mine\n          </label>\n          <ObligationCalendar workspaceId={workspaceId} orgSlug={orgSlug} workspaceSlug={workspaceSlug} mine={mine} />\n        </div>\n      ) : null}\n      {tab === "holidays" ? <HolidayCalendars workspaceId={workspaceId} isAdmin={isAdmin} /> : null}\n      {tab === "feeds" ? <CalendarFeeds workspaceId={workspaceId} /> : null}\n    </div>\n  );\n};\n\nexport default Obligations;\n'),
    Op(path='frontend/src/pages/public/DocumentRequestUpload.tsx', kind='edit', final_sha='104f5f12b5725c0cfeafd7c8a0514988afbe2e4f0860c64e4cae4511b4315fdd',
       variants=(('3b7ed4e957ec87baa216a13687e5b940baa1a906d6e0b028a3886617a67935d9', (('            </p>\n            <p className={HINT}>This link works once and expires {new Date(info.data.expires_at).toLocaleString()}.</p>\n            <input type="file" accept=".pdf,image/*" aria-label="Document" onChange={(e) => setFile(e.target.files?.[0] ?? null)} />\n', '            </p>\n            <p className={HINT}>This link works once and expires {formatTimestamp(info.data.expires_at)}.</p>\n            <input type="file" accept=".pdf,image/*" aria-label="Document" onChange={(e) => setFile(e.target.files?.[0] ?? null)} />\n'), ('import { errorMessage } from "@/services/api/errors";\n\n', 'import { errorMessage } from "@/services/api/errors";\n// ARCH46-S2:h8-timestamps — instants follow the reader\'s profile zone and language (ARCH-30 D-5; verify_arch30_tranche3 H8).\nimport { formatTimestamp } from "@/utils/displayTime";\n\n'))),),
       content=''),
    Op(path='frontend/src/routes/tenantPaths.ts', kind='edit', final_sha='61b5d82281aa07e884bfe991afae8e4348f8d77b8b31b43d451bc51a052bcc1e',
       variants=(('11520ad2c5f8e191bce3aa0ab2db3050db4d3a9c6b7aed26c42c20f06b1de404', (('  `${tablesPath(orgSlug, workspaceSlug)}/${encodeURIComponent(tableId)}`;\n// ARCH45-S2:corroboration-path-helpers\n', '  `${tablesPath(orgSlug, workspaceSlug)}/${encodeURIComponent(tableId)}`;\n// ARCH46-S2:obligation-path-helpers\nexport const obligationsPath = (orgSlug: string, workspaceSlug: string): string =>\n  `${workspacePath(orgSlug, workspaceSlug)}/obligations`;\nexport const obligationPath = (orgSlug: string, workspaceSlug: string, obligationId: string): string =>\n  `${obligationsPath(orgSlug, workspaceSlug)}/${encodeURIComponent(obligationId)}`;\n// ARCH45-S2:corroboration-path-helpers\n'), ('  workspaceCorroboration: "corroboration/:runId",\n  // ARCH-36. ARCH-33\'s assertion review queue. A child of the workspace\n', '  workspaceCorroboration: "corroboration/:runId",\n  // ARCH46-S2:route-patterns\n  workspaceObligations: "obligations",\n  workspaceObligation: "obligations/:obligationId",\n  // ARCH-36. ARCH-33\'s assertion review queue. A child of the workspace\n'))),),
       content=''),
    Op(path='frontend/src/services/api/obligations.ts', kind='new', final_sha='d73501cd2bd72627f27d89d83804637ad1b2aeb7ed46cb8782a5e6c7351442cf',
       variants=(),
       content='/** ARCH46-S2:api-client — obligations, holiday calendars and calendar feeds. Every route is gated on capability.obligations. */\nimport { apiClient, apiHref } from "@/services/api/client";\nimport { downloadBlob } from "@/services/api/audit";\nimport type {\n  CalendarUpdateResult, CalendarView, DateCalculation, DateCalculationRequest, DocumentObligations, EntityObligations,\n  ExtractResult, FeedCreate, FeedIssued, FeedList, HolidayCalendarCreate, HolidayCalendarList, HolidayCalendarRow,\n  HolidayCalendarUpdate, ObligationCreate, ObligationDetail, ObligationList, ObligationUpdate, ObligationVerdict,\n} from "@/types/obligations";\n\nconst ws = (workspaceId: string): string => `/workspaces/${encodeURIComponent(workspaceId)}`;\nconst one = (workspaceId: string, id: string): string => `${ws(workspaceId)}/obligations/${encodeURIComponent(id)}`;\n\nexport interface ObligationFilters {\n  readonly state?: string;\n  readonly kind?: string;\n  readonly review?: string;\n  readonly owner?: string;\n  readonly q?: string;\n  readonly due_from?: string;\n  readonly due_to?: string;\n  readonly entity_id?: string;\n  readonly work_item_id?: string;\n  readonly include_rejected?: boolean;\n  readonly limit?: number;\n}\n\nexport const obligationKeys = {\n  all: (workspaceId: string) => ["obligations", workspaceId] as const,\n  list: (workspaceId: string, filters: ObligationFilters) => ["obligations", workspaceId, "list", filters] as const,\n  calendar: (workspaceId: string, from: string, to: string, owner: string) =>\n    ["obligations", workspaceId, "calendar", from, to, owner] as const,\n  detail: (workspaceId: string, id: string) => ["obligations", workspaceId, "detail", id] as const,\n  document: (workspaceId: string, workItemId: string) => ["obligations", workspaceId, "document", workItemId] as const,\n  entity: (workspaceId: string, entityId: string) => ["obligations", workspaceId, "entity", entityId] as const,\n  calendars: (workspaceId: string) => ["obligations", workspaceId, "holiday-calendars"] as const,\n  feeds: (workspaceId: string) => ["obligations", workspaceId, "feeds"] as const,\n};\n\nconst clean = (filters: ObligationFilters): Record<string, string | number | boolean> => {\n  const out: Record<string, string | number | boolean> = {};\n  for (const [key, value] of Object.entries(filters)) {\n    if (value !== undefined && value !== null && value !== "") {\n      out[key] = value as string | number | boolean;\n    }\n  }\n  return out;\n};\n\nexport const listObligations = async (workspaceId: string, filters: ObligationFilters = {}): Promise<ObligationList> =>\n  (await apiClient.get<ObligationList>(`${ws(workspaceId)}/obligations`, { params: clean(filters) })).data;\n\nexport const getCalendar = async (workspaceId: string, from: string, to: string, owner?: string): Promise<CalendarView> =>\n  (await apiClient.get<CalendarView>(`${ws(workspaceId)}/obligations/calendar`,\n    { params: owner ? { from, to, owner } : { from, to } })).data;\n\nexport const createObligation = async (workspaceId: string, body: ObligationCreate): Promise<ObligationDetail> =>\n  (await apiClient.post<ObligationDetail>(`${ws(workspaceId)}/obligations`, body)).data;\n\nexport const getObligation = async (workspaceId: string, id: string): Promise<ObligationDetail> =>\n  (await apiClient.get<ObligationDetail>(one(workspaceId, id))).data;\n\nexport const updateObligation = async (workspaceId: string, id: string, body: ObligationUpdate): Promise<ObligationDetail> =>\n  (await apiClient.patch<ObligationDetail>(one(workspaceId, id), body)).data;\n\nexport const completeObligation = async (workspaceId: string, id: string, note?: string): Promise<ObligationDetail> =>\n  (await apiClient.post<ObligationDetail>(`${one(workspaceId, id)}/complete`, note ? { note } : {})).data;\n\nexport const waiveObligation = async (workspaceId: string, id: string, reason: string): Promise<ObligationDetail> =>\n  (await apiClient.post<ObligationDetail>(`${one(workspaceId, id)}/waive`, { reason })).data;\n\nexport const reopenObligation = async (workspaceId: string, id: string): Promise<ObligationDetail> =>\n  (await apiClient.post<ObligationDetail>(`${one(workspaceId, id)}/reopen`)).data;\n\nexport const reviewObligation = async (workspaceId: string, id: string, verdict: ObligationVerdict): Promise<ObligationDetail> =>\n  (await apiClient.post<ObligationDetail>(`${one(workspaceId, id)}/review`, { verdict })).data;\n\nexport const deleteObligation = async (workspaceId: string, id: string): Promise<void> => {\n  await apiClient.delete(one(workspaceId, id));\n};\n\nexport const calculateDate = async (workspaceId: string, body: DateCalculationRequest): Promise<DateCalculation> =>\n  (await apiClient.post<DateCalculation>(`${ws(workspaceId)}/obligations/calculate`, body)).data;\n\nexport const getDocumentObligations = async (workspaceId: string, workItemId: string): Promise<DocumentObligations> =>\n  (await apiClient.get<DocumentObligations>(`${ws(workspaceId)}/work-items/${encodeURIComponent(workItemId)}/obligations`)).data;\n\nexport const extractDocumentObligations = async (workspaceId: string, workItemId: string): Promise<ExtractResult> =>\n  (await apiClient.post<ExtractResult>(\n    `${ws(workspaceId)}/work-items/${encodeURIComponent(workItemId)}/obligations/extract`)).data;\n\nexport const getEntityObligations = async (workspaceId: string, entityId: string): Promise<EntityObligations> =>\n  (await apiClient.get<EntityObligations>(`${ws(workspaceId)}/entities/${encodeURIComponent(entityId)}/obligations`)).data;\n\nexport const listHolidayCalendars = async (workspaceId: string): Promise<HolidayCalendarList> =>\n  (await apiClient.get<HolidayCalendarList>(`${ws(workspaceId)}/holiday-calendars`)).data;\n\nexport const createHolidayCalendar = async (workspaceId: string, body: HolidayCalendarCreate): Promise<HolidayCalendarRow> =>\n  (await apiClient.post<HolidayCalendarRow>(`${ws(workspaceId)}/holiday-calendars`, body)).data;\n\nexport const updateHolidayCalendar = async (\n  workspaceId: string, calendarId: string, body: HolidayCalendarUpdate,\n): Promise<CalendarUpdateResult> =>\n  (await apiClient.patch<CalendarUpdateResult>(`${ws(workspaceId)}/holiday-calendars/${encodeURIComponent(calendarId)}`,\n    body)).data;\n\nexport const deleteHolidayCalendar = async (workspaceId: string, calendarId: string): Promise<void> => {\n  await apiClient.delete(`${ws(workspaceId)}/holiday-calendars/${encodeURIComponent(calendarId)}`);\n};\n\nexport const listFeeds = async (workspaceId: string): Promise<FeedList> =>\n  (await apiClient.get<FeedList>(`${ws(workspaceId)}/calendar-feeds`)).data;\n\n/** The token is in this response only; the server keeps its SHA-256. */\nexport const issueFeed = async (workspaceId: string, body: FeedCreate): Promise<FeedIssued> =>\n  (await apiClient.post<FeedIssued>(`${ws(workspaceId)}/calendar-feeds`, body)).data;\n\nexport const revokeFeed = async (workspaceId: string, feedId: string): Promise<void> => {\n  await apiClient.delete(`${ws(workspaceId)}/calendar-feeds/${encodeURIComponent(feedId)}`);\n};\n\n/**\n * The absolute feed URL a calendar app subscribes to, composed from the API\n * base and the token (never from a URL string in a response body): https for\n * copying, webcal for "open in my calendar".\n */\nexport const feedUrls = (token: string): { readonly https: string; readonly webcal: string } => {\n  const https = new URL(apiHref(`/public/calendar-feeds/${encodeURIComponent(token)}.ics`), window.location.origin).toString();\n  return { https, webcal: https.replace(/^https?:/, "webcal:") };\n};\n\n/** A one-off export (the session authorises it, so it goes through the API client). */\nexport const downloadObligations = async (workspaceId: string, format: "ics" | "csv"): Promise<void> => {\n  const response = await apiClient.get<Blob>(`${ws(workspaceId)}/obligations/export`, {\n    params: { format }, responseType: "blob", timeout: 120_000,\n  });\n  downloadBlob(response.data, `obligations.${format}`);\n};\n'),
    Op(path='frontend/src/types/obligations.ts', kind='new', final_sha='f5eb1ba974ee882db7dd02bf800e13f02fa88765b87e93c5ff94e5c2061e8daf',
       variants=(),
       content='/**\n * ARCH46-S2:types — Obligations & Temporal Intelligence. Mirrors\n * backend/app/schemas/obligations.py field for field (verify_arch46 W3 compares\n * them) and the vocabulary in backend/app/services/obligations/vocabulary.py.\n */\n\nimport { formatCalendarDate } from "@/utils/displayTime";\n\nexport type ObligationKind = "RENEWAL" | "NOTICE" | "PAYMENT" | "DELIVERY" | "EXPIRY" | "REPORTING" | "OTHER";\nexport type ObligationState = "OPEN" | "DUE_SOON" | "OVERDUE" | "DONE" | "WAIVED";\nexport type ObligationReview = "AUTO" | "PENDING" | "CONFIRMED" | "REJECTED";\nexport type ObligationOrigin = "EXTRACTED" | "MANUAL";\nexport type RuleKind = "FIXED" | "OFFSET" | "SERIES" | "NONE";\nexport type PeriodUnit = "DAY" | "BUSINESS_DAY" | "WEEK" | "MONTH" | "YEAR";\nexport type RollConvention = "NONE" | "FOLLOWING" | "PRECEDING" | "MODIFIED_FOLLOWING";\nexport type ObligationEventKind =\n  | "CREATED" | "UPDATED" | "DUE_SOON" | "OVERDUE" | "REOPENED" | "DONE" | "WAIVED" | "ADVANCED" | "RESCHEDULED"\n  | "CONFIRMED" | "REJECTED" | "SUPERSEDED";\nexport type FeedScope = "ALL" | "MINE";\nexport type CalendarSource = "TEMPLATE" | "MANUAL" | "ICS";\nexport type ObligationVerdict = "CONFIRM" | "REJECT";\n\nexport const KINDS: readonly ObligationKind[] = ["RENEWAL", "NOTICE", "PAYMENT", "DELIVERY", "EXPIRY", "REPORTING", "OTHER"];\nexport const STATES: readonly ObligationState[] = ["OPEN", "DUE_SOON", "OVERDUE", "DONE", "WAIVED"];\nexport const UNITS: readonly PeriodUnit[] = ["DAY", "BUSINESS_DAY", "WEEK", "MONTH", "YEAR"];\nexport const ROLLS: readonly RollConvention[] = ["NONE", "FOLLOWING", "PRECEDING", "MODIFIED_FOLLOWING"];\n\nexport const KIND_LABELS: Readonly<Record<ObligationKind, string>> = {\n  RENEWAL: "Renewal",\n  NOTICE: "Notice deadline",\n  PAYMENT: "Payment",\n  DELIVERY: "Delivery",\n  EXPIRY: "Expiry",\n  REPORTING: "Report",\n  OTHER: "Other",\n};\n\nexport const STATE_LABELS: Readonly<Record<ObligationState, string>> = {\n  OPEN: "Open",\n  DUE_SOON: "Due soon",\n  OVERDUE: "Overdue",\n  DONE: "Done",\n  WAIVED: "Waived",\n};\n\nexport const STATE_TONE: Readonly<Record<ObligationState, string>> = {\n  OPEN: "bg-muted text-muted-foreground",\n  DUE_SOON: "bg-amber-500/15 text-amber-700 dark:text-amber-300",\n  OVERDUE: "bg-destructive/15 text-destructive",\n  DONE: "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300",\n  WAIVED: "bg-muted text-muted-foreground line-through",\n};\n\nexport const REVIEW_LABELS: Readonly<Record<ObligationReview, string>> = {\n  AUTO: "Read from the document",\n  PENDING: "Needs confirming",\n  CONFIRMED: "Confirmed",\n  REJECTED: "Rejected",\n};\n\nexport const UNIT_LABELS: Readonly<Record<PeriodUnit, string>> = {\n  DAY: "days",\n  BUSINESS_DAY: "business days",\n  WEEK: "weeks",\n  MONTH: "months",\n  YEAR: "years",\n};\n\nexport const ROLL_LABELS: Readonly<Record<RollConvention, string>> = {\n  NONE: "Keep the date",\n  FOLLOWING: "Next business day",\n  PRECEDING: "Previous business day",\n  MODIFIED_FOLLOWING: "Next business day, unless that is next month",\n};\n\nexport const WEEKDAY_LABELS: readonly string[] = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];\n\nexport interface PeriodSpec {\n  readonly n: number;\n  readonly unit: string;\n}\n\nexport interface RuleSpec {\n  readonly kind: string;\n  readonly date?: string | null;\n  readonly anchor_obligation_id?: string | null;\n  readonly anchor_date?: string | null;\n  readonly sign?: number | null;\n  readonly period?: PeriodSpec | null;\n  readonly shift_days?: number | null;\n  readonly rrule?: string | null;\n  readonly start?: string | null;\n  readonly roll?: string | null;\n}\n\nexport interface ObligationCreate {\n  readonly kind: string;\n  readonly title: string;\n  readonly description?: string | null;\n  readonly rule: RuleSpec;\n  readonly owner_user_id?: string | null;\n  readonly entity_id?: string | null;\n  readonly work_item_id?: string | null;\n  readonly calendar_id?: string | null;\n  readonly lead_days?: number | null;\n  readonly amount?: number | null;\n  readonly currency?: string | null;\n  readonly counterparty_name?: string | null;\n}\n\nexport interface ObligationUpdate {\n  readonly title?: string | null;\n  readonly description?: string | null;\n  readonly owner_user_id?: string | null;\n  readonly entity_id?: string | null;\n  readonly calendar_id?: string | null;\n  readonly lead_days?: number | null;\n  readonly kind?: string | null;\n  readonly amount?: number | null;\n  readonly currency?: string | null;\n  readonly counterparty_name?: string | null;\n  readonly due_date?: string | null;\n  readonly rule?: RuleSpec | null;\n  readonly business_day_rule?: string | null;\n}\n\nexport interface ObligationBrief {\n  readonly id: string;\n  readonly kind: ObligationKind;\n  readonly title: string;\n  readonly due_date?: string | null;\n  readonly state: ObligationState;\n}\n\nexport interface ObligationRow {\n  readonly id: string;\n  readonly kind: ObligationKind;\n  readonly title: string;\n  readonly state: ObligationState;\n  readonly review: ObligationReview;\n  readonly origin: ObligationOrigin;\n  readonly due_date?: string | null;\n  readonly days_until?: number | null;\n  readonly lead_days: number;\n  readonly recurrence?: string | null;\n  readonly recurrence_text?: string | null;\n  readonly occurrence: number;\n  readonly completed_occurrences: number;\n  readonly business_day_rule: RollConvention;\n  readonly calendar_id?: string | null;\n  readonly anchor_obligation_id?: string | null;\n  readonly owner_user_id?: string | null;\n  readonly owner_email?: string | null;\n  readonly entity_id?: string | null;\n  readonly entity_root_id?: string | null;\n  readonly entity_name?: string | null;\n  readonly counterparty_name?: string | null;\n  readonly work_item_id?: string | null;\n  readonly work_item_filename?: string | null;\n  readonly amount?: string | null;\n  readonly currency?: string | null;\n  readonly confidence: number;\n  readonly reasons: readonly string[];\n  readonly superseded: boolean;\n  readonly created_at: string;\n  readonly updated_at: string;\n  readonly state_changed_at: string;\n}\n\nexport interface ObligationList {\n  readonly items: readonly ObligationRow[];\n  readonly total: number;\n  readonly counts_by_state: Readonly<Record<string, number>>;\n  readonly pending_review: number;\n  readonly today: string;\n  readonly timezone: string;\n}\n\nexport interface ObligationEventRow {\n  readonly id: string;\n  readonly kind: ObligationEventKind;\n  readonly from_state?: ObligationState | null;\n  readonly to_state?: ObligationState | null;\n  readonly due_date?: string | null;\n  readonly occurrence?: number | null;\n  readonly emitted: boolean;\n  readonly actor_user_id?: string | null;\n  readonly detail: Readonly<Record<string, unknown>>;\n  readonly created_at: string;\n}\n\nexport interface OccurrenceRow {\n  readonly occurrence: number;\n  readonly due_date: string;\n}\n\nexport interface EvidenceSpan {\n  readonly page: number;\n  readonly text?: string;\n  readonly work_item_id?: string;\n  readonly bbox?: { readonly x0: number; readonly y0: number; readonly x1: number; readonly y1: number };\n}\n\nexport interface ObligationDetail {\n  readonly obligation: ObligationRow;\n  readonly description?: string | null;\n  readonly due_rule: Readonly<Record<string, unknown>>;\n  readonly derivation: readonly string[];\n  readonly evidence: readonly EvidenceSpan[];\n  readonly quote?: string | null;\n  readonly clause_number?: string | null;\n  readonly detail: Readonly<Record<string, unknown>>;\n  readonly events: readonly ObligationEventRow[];\n  readonly upcoming: readonly OccurrenceRow[];\n  readonly anchor?: ObligationBrief | null;\n  readonly dependents: readonly ObligationBrief[];\n  readonly done_at?: string | null;\n  readonly done_by_user_id?: string | null;\n  readonly waived_at?: string | null;\n  readonly waiver_reason?: string | null;\n  readonly reviewed_at?: string | null;\n  readonly reviewed_by_user_id?: string | null;\n  readonly engine_version?: string | null;\n  readonly calendar_name?: string | null;\n  readonly today: string;\n  readonly timezone: string;\n}\n\nexport interface CalendarOccurrence {\n  readonly obligation_id: string;\n  readonly occurrence: number;\n  readonly due_date: string;\n  readonly kind: ObligationKind;\n  readonly title: string;\n  readonly state: ObligationState;\n  readonly review: ObligationReview;\n  readonly owner_user_id?: string | null;\n  readonly projected: boolean;\n}\n\nexport interface CalendarView {\n  readonly from_date: string;\n  readonly to_date: string;\n  readonly today: string;\n  readonly timezone: string;\n  readonly items: readonly CalendarOccurrence[];\n}\n\nexport interface CompleteRequest {\n  readonly note?: string | null;\n}\n\nexport interface WaiveRequest {\n  readonly reason: string;\n}\n\nexport interface ReviewRequest {\n  readonly verdict: string;\n}\n\nexport interface ExtractResult {\n  readonly extracted: boolean;\n  readonly created: number;\n  readonly kept: number;\n  readonly revived: number;\n  readonly superseded: number;\n  readonly pending: number;\n  readonly engine_version: string;\n}\n\nexport interface DocumentObligations {\n  readonly work_item_id: string;\n  readonly original_filename: string;\n  readonly items: readonly ObligationRow[];\n  readonly today: string;\n}\n\nexport interface EntityObligations {\n  readonly entity_id: string;\n  readonly root_id: string;\n  readonly items: readonly ObligationRow[];\n  readonly today: string;\n}\n\nexport interface HolidayRow {\n  readonly date: string;\n  readonly name: string;\n}\n\nexport interface TemplateRow {\n  readonly code: string;\n  readonly name: string;\n  readonly region: string;\n  readonly weekend_days: readonly number[];\n  readonly description: string;\n}\n\nexport interface HolidayCalendarRow {\n  readonly id: string;\n  readonly name: string;\n  readonly source: CalendarSource;\n  readonly template_code?: string | null;\n  readonly region?: string | null;\n  readonly weekend_days: readonly number[];\n  readonly holidays: readonly HolidayRow[];\n  readonly is_default: boolean;\n  readonly revision: number;\n  readonly obligations: number;\n  readonly updated_at: string;\n}\n\nexport interface HolidayCalendarList {\n  readonly items: readonly HolidayCalendarRow[];\n  readonly templates: readonly TemplateRow[];\n}\n\nexport interface HolidayCalendarCreate {\n  readonly name: string;\n  readonly template?: string | null;\n  readonly years?: readonly number[];\n  readonly holidays?: readonly HolidayRow[];\n  readonly ics?: string | null;\n  readonly weekend_days?: readonly number[] | null;\n  readonly is_default?: boolean;\n}\n\nexport interface HolidayCalendarUpdate {\n  readonly name?: string | null;\n  readonly holidays?: readonly HolidayRow[] | null;\n  readonly weekend_days?: readonly number[] | null;\n  readonly is_default?: boolean | null;\n}\n\nexport interface CalendarUpdateResult {\n  readonly calendar: HolidayCalendarRow;\n  readonly rescheduled: number;\n}\n\nexport interface FeedRow {\n  readonly id: string;\n  readonly label: string;\n  readonly scope: FeedScope;\n  readonly include_closed: boolean;\n  readonly user_id: string;\n  readonly mine: boolean;\n  readonly created_at: string;\n  readonly expires_at?: string | null;\n  readonly last_used_at?: string | null;\n  readonly use_count: number;\n  readonly revoked_at?: string | null;\n}\n\nexport interface FeedList {\n  readonly items: readonly FeedRow[];\n}\n\nexport interface FeedCreate {\n  readonly label?: string | null;\n  readonly scope: string;\n  readonly include_closed?: boolean;\n  readonly expires_in_days?: number | null;\n}\n\nexport interface FeedIssued {\n  readonly feed: FeedRow;\n  readonly token: string;\n  readonly path: string;\n}\n\nexport interface DateCalculationRequest {\n  readonly rule: RuleSpec;\n  readonly anchor_due?: string | null;\n  readonly calendar_id?: string | null;\n  readonly occurrences?: number;\n}\n\nexport interface DateCalculation {\n  readonly due_date?: string | null;\n  readonly steps: readonly string[];\n  readonly upcoming: readonly OccurrenceRow[];\n}\n\n/** "in 3 days", "today", "2 days overdue". */\nexport const dueLabel = (row: Pick<ObligationRow, "days_until" | "state">): string => {\n  const d = row.days_until;\n  if (d === null || d === undefined) {\n    return "no date yet";\n  }\n  if (row.state === "DONE" || row.state === "WAIVED") {\n    return "";\n  }\n  if (d === 0) {\n    return "today";\n  }\n  if (d > 0) {\n    return d === 1 ? "tomorrow" : `in ${d} days`;\n  }\n  return -d === 1 ? "1 day overdue" : `${-d} days overdue`;\n};\n\n/** A YYYY-MM-DD date as a readable local date (it IS a local date: no time zone shift; the profile\'s language). */\nexport const formatDay = (iso?: string | null): string => formatCalendarDate(iso);\n'),
